-- lua/pure/dashboard.lua
package.preload["pure.dashboard"] = function(...)
-- ~/.config/nvim/lua/Custom_dashboard.lua

local M = {}

-- State to hold your original UI options
M.state = {
  is_active = false,
  user_laststatus = nil,
  user_showtabline = nil,
  user_winbar = nil,
  user_cursorline = nil,
  user_number = nil,
  user_relativenumber = nil,
}

-- Configuration for which UI elements to hide on the dashboard
local dashboard_ui_opts = {
  hide = {
    statusline = true,
    tabline = true,
    winbar = true,
    cursorline = true,
    number = true,
    relativenumber = true,
  }
}

-- Saves your current UI options
function M.save_ui_options()
  M.state.user_laststatus = vim.opt.laststatus:get()
  M.state.user_showtabline = vim.opt.showtabline:get()
  M.state.user_winbar = vim.opt.winbar:get()
  M.state.user_cursorline = vim.opt.cursorline:get()
  M.state.user_number = vim.opt.number:get()
  M.state.user_relativenumber= vim.opt.relativenumber:get()
  M.state.is_active = true
end

-- Applies the special UI settings for the dashboard
function M.set_dashboard_ui()
  if dashboard_ui_opts.hide.statusline then vim.opt.laststatus = 0 end
  if dashboard_ui_opts.hide.tabline then vim.opt.showtabline = 0 end
  if dashboard_ui_opts.hide.winbar then vim.opt.winbar = '' end
  if dashboard_ui_opts.hide.cursorline then vim.opt.cursorline = false end
  if dashboard_ui_opts.hide.number then vim.opt.number = false end
  if dashboard_ui_opts.hide.relativenumber then vim.opt.relativenumber = false end
end

-- Restores your original UI options
function M.restore_ui_options()
  if not M.state.is_active then return end

  vim.opt.laststatus = M.state.user_laststatus
  vim.opt.showtabline = M.state.user_showtabline
  vim.opt.winbar = M.state.user_winbar
  vim.opt.cursorline = M.state.user_cursorline
  -- number/relativenumber were saved and hidden but never restored, so line
  -- numbers stayed off for the rest of the session after leaving the dashboard.
  vim.opt.number = M.state.user_number
  vim.opt.relativenumber = M.state.user_relativenumber

  -- Reset state to indicate dashboard is no longer controlling the UI
  M.state.is_active = false
end

-- Creates a single, robust autocommand to manage UI state.
-- This is inspired by the logic in dashboard.nvim.
local function setup_ui_management_autocommand()
  local group = vim.api.nvim_create_augroup('CustomDashboardUIMgmt', { clear = true })
  vim.api.nvim_create_autocmd('BufEnter', {
    group = group,
    callback = function(args)
      -- When entering a dashboard buffer, ensure its special UI is set
      if vim.bo[args.buf].filetype == 'dashboard' then
        M.set_dashboard_ui()
        return
      end

      -- If we are in a normal buffer, check if we should restore the original UI
      if M.state.is_active then
        local dashboard_is_visible = false
        for _, win in ipairs(vim.api.nvim_list_wins()) do
          if vim.bo[vim.api.nvim_win_get_buf(win)].filetype == 'dashboard' then
            dashboard_is_visible = true
            break
          end
        end

        if not dashboard_is_visible then
          M.restore_ui_options()
          -- The autocommand has done its job, so we can remove it.
          vim.api.nvim_del_augroup_by_name('CustomDashboardUIMgmt')
        end
      end
    end,
  })
end

--- The art without its surrounding blank space: trailing blank lines dropped
--- and the indentation shared by every line removed, so it can be centred.
local function trimArt(lines)
  local out = vim.deepcopy(lines)
  while #out > 0 and out[#out]:match('^%s*$') do table.remove(out) end
  local indent = math.huge
  for _, l in ipairs(out) do
    if l:match('%S') then indent = math.min(indent, #l:match('^%s*')) end
  end
  if indent == math.huge then indent = 0 end
  for i, l in ipairs(out) do out[i] = l:sub(indent + 1):gsub('%s+$', '') end
  return out
end

--- Scale the art by `k`: each character repeated k times, each line k times,
--- which keeps its proportions (a cell is about twice as tall as wide either
--- way). Menu lines ("[n] New File ...") are text, so they are left as is.
local function scaleArt(lines, k)
  if k <= 1 then return lines end
  local out = {}
  for _, l in ipairs(lines) do
    if l:match('%[%a%]') then
      table.insert(out, l)
    else
      local wide = table.concat(vim.tbl_map(function(c) return c:rep(k) end, vim.fn.split(l, [[\zs]])))
      for _ = 1, k do table.insert(out, wide) end
    end
  end
  return out
end

--- Fill the window with the art centred in it, at the largest scale that fits
--- (vim.g.pure_dashboard_scale: 'auto', the default, or a fixed number).
--- It used to be written as is, at the top left: in a big or full-screen
--- window the planet sat in one corner.
local function render(buf, win)
  if not (vim.api.nvim_buf_is_valid(buf) and vim.api.nvim_win_is_valid(win)) then return end
  local art = trimArt(require('pure.ascii').saturn)
  local width, height = vim.api.nvim_win_get_width(win), vim.api.nvim_win_get_height(win)

  local art_w = 0
  for _, l in ipairs(art) do art_w = math.max(art_w, vim.fn.strdisplaywidth(l)) end
  local setting = vim.g.pure_dashboard_scale or 'auto'
  local k = tonumber(setting) or 1
  if setting == 'auto' then
    k = math.max(1, math.min(math.floor(width / math.max(art_w, 1)), math.floor(height / math.max(#art, 1))))
  end
  local lines = scaleArt(art, k)

  -- One left margin for the whole drawing, so it keeps its shape; the menu
  -- line is centred on its own.
  local block_w = 0
  for _, l in ipairs(lines) do
    if not l:match('%[%a%]') then block_w = math.max(block_w, vim.fn.strdisplaywidth(l)) end
  end
  local left = string.rep(' ', math.max(0, math.floor((width - block_w) / 2)))
  local out, menu_row = {}, 1
  for _ = 1, math.max(0, math.floor((height - #lines) / 2)) do table.insert(out, '') end
  for _, l in ipairs(lines) do
    if l:match('%[%a%]') then
      local pad = math.max(0, math.floor((width - vim.fn.strdisplaywidth(l)) / 2))
      table.insert(out, string.rep(' ', pad) .. l)
      menu_row = #out
    else
      table.insert(out, l ~= '' and (left .. l) or '')
    end
  end

  vim.bo[buf].modifiable = true
  vim.api.nvim_buf_set_lines(buf, 0, -1, false, out)
  vim.bo[buf].modifiable = false
  -- Rest the cursor on the menu line, out of the drawing.
  pcall(vim.api.nvim_win_set_cursor, win, { menu_row, 0 })
end

-- Your function to draw the dashboard, now with UI management
function M.drawDashboard()
  -- If the dashboard isn't already active, save the current UI state
  -- and set up the autocommand to manage restoring it.
  if not M.state.is_active then
    M.save_ui_options()
    setup_ui_management_autocommand()
  end

  local buf = vim.api.nvim_create_buf(false, true)

  -- Set buffer options
  vim.bo[buf].filetype = 'dashboard'
  vim.bo[buf].bufhidden = 'wipe'
  vim.bo[buf].buftype = 'nofile'
  vim.bo[buf].swapfile = false

  -- Apply dashboard-specific UI settings now
  M.set_dashboard_ui()

  vim.api.nvim_win_set_buf(0, buf)
  render(buf, vim.api.nvim_get_current_win())

  -- Redraw centred (and rescaled) whenever the window changes size: going
  -- full screen, a split, a font change.
  vim.api.nvim_create_autocmd({ 'VimResized', 'WinResized' }, {
    callback = function()
      if not vim.api.nvim_buf_is_valid(buf) then return true end -- drop the autocmd
      local win = vim.fn.bufwinid(buf)
      if win ~= -1 then render(buf, win) end
    end,
  })

  -- Set your keymaps for the dashboard buffer
  local opts = { buffer = buf, silent = true, nowait = true }
  vim.keymap.set('n', 'n', ':enew<CR>', opts)
  vim.keymap.set('n', 'q', ':qa<CR>', opts)
  vim.keymap.set('n', 'u', function()
    if vim.pack.update then
      vim.pack.update()
    else
      print("vim.pack.update is not defined.")
    end
  end, opts)
end

return M

end

-- lua/pure/folding.lua
package.preload["pure.folding"] = function(...)
local M = {}
local fold_group = vim.api.nvim_create_augroup("PureFoldingAuto", { clear = true })

-- -----------------------------------------------------------------------------
-- Exemplo: "function foo() ... (15 lines)"
function _G.PureFoldText()
    local pos = vim.v.foldstart
    local line = vim.api.nvim_buf_get_lines(0, pos - 1, pos, false)[1]
    local lines_count = vim.v.foldend - vim.v.foldstart + 1

    local clean_line = line:gsub("^%s+", ""):gsub("%s+$", "")

    return clean_line .. " ... 󰁂 " .. lines_count .. " linhas "
end

-- Automatic folds for the current window: treesitter when the buffer has a
-- parser, indentation otherwise. Also what <leader>zr goes back to after
-- folding by hand; the manual folds are dropped then.
function M.auto()
    local ok, parser = pcall(vim.treesitter.get_parser)

    -- The fallback used to sit *inside* the success branch, where `ok` is
    -- always true, so it was dead code and buffers without a parser kept
    -- whatever foldmethod happened to be set.
    if ok and parser then
        vim.opt_local.foldmethod = "expr"
        vim.opt_local.foldexpr = "v:lua.vim.treesitter.foldexpr()"
    else
        vim.opt_local.foldmethod = "indent"
    end
end

vim.api.nvim_create_autocmd("FileType", {
    group = fold_group,
    pattern = "*",
    callback = M.auto,
})

return M

end

-- lua/pure/fuzzyUtils.lua
package.preload["pure.fuzzyUtils"] = function(...)
local M = {}
local func = require('configs.functions')
local terms = require('pure.terms')
-- Every path handed to the shell is shellescape()d: this user's home is
-- "C:/Users/Mia Schionato", and an unquoted path broke at the space, so the
-- command died instantly and the floating window just blinked shut.
local cache_dir = vim.fn.stdpath("cache") if vim.fn.isdirectory(cache_dir) == 0 then vim.fn.mkdir(cache_dir, "p") end

-- Directories the pickers never descend into. `fd --hidden` walks straight into
-- .git and buries real results under dozens of internal files, and `ls -a`
-- lists it too. ripgrep already skips it on its own, so fuzzyGrep needs nothing.
--
-- ".obsidian" is the vault's own config directory: it holds hundreds of json
-- and plugin files that drown out the actual notes.
--
-- Override with, for example:
--   vim.g.pure_fuzzy_ignore = { ".git", ".obsidian", "node_modules", "target" }
local function ignoredDirs()
  return vim.g.pure_fuzzy_ignore or { ".git", ".obsidian" }
end

--- Guarantee a single trailing slash.
---
--- The pickers build the final file name with `path .. selection`, so a caller
--- passing ".../Atlas" instead of ".../Atlas/" silently produced
--- ".../Atlasnote.md". Normalising here keeps every call site in keymaps.lua
--- from having to remember the slash.
--- @param path string|nil
--- @return string|nil
local function asDir(path)
  if path == nil or path == "" then
    return path
  end
  return (path:gsub("[/\\]+$", "")) .. "/"
end

--- @return string flags for fd, e.g. --exclude '.git'
local function fdExcludes()
  local parts = {}
  for _, dir in ipairs(ignoredDirs()) do
    table.insert(parts, "--exclude " .. vim.fn.shellescape(dir))
  end
  return table.concat(parts, " ")
end

--- @return string flags for ls, e.g. --ignore='.git'
---
--- Filtering inside ls rather than grepping its output is deliberate:
--- `ls --color=always` emits the reset sequence *between* the name and the
--- trailing slash (".git<ESC>[0m/"), so a plain `grep -v '\.git/$'` never
--- matches. '.' and '..' survive --ignore, so navigation still works.
local function lsIgnores()
  local parts = {}
  for _, dir in ipairs(ignoredDirs()) do
    table.insert(parts, "--ignore=" .. vim.fn.shellescape(dir))
  end
  return table.concat(parts, " ")
end

-- fzf starts its child processes (--preview above all) through its own shell,
-- which on Windows is cmd.exe -- not Neovim's 'shell'. The preview commands in
-- this file are POSIX ("if [ -d {} ]; then ... fi"), so cmd.exe answered with
-- "-d was unexpected at this time." and the picker closed the instant it opened.
--
-- Point fzf at the same bash Neovim already validated in init.lua. Set through
-- FZF_DEFAULT_OPTS so every picker in this file inherits it. Needs fzf >= 0.52
-- for --with-shell; older builds ignore the unknown option in the env var.
local function appendFzfOpts(extra)
  local existing = vim.env.FZF_DEFAULT_OPTS
  vim.env.FZF_DEFAULT_OPTS = existing and (existing .. " " .. extra) or extra
end

if vim.fn.has("win32") == 1 then
  local sh = vim.o.shell
  if not sh:lower():find("bash", 1, true) then
    sh = vim.fn.exepath("bash")
  end
  if sh ~= "" then
    appendFzfOpts('--with-shell "' .. vim.fs.normalize(sh) .. ' -c"')
  end
end

-- These pickers already run inside a dedicated floating window, so fzf must not
-- size or frame itself again.
--
-- A shell profile that exports FZF_DEFAULT_OPTS for interactive use (this one
-- sets "--height=60% --border") leaked into Neovim: fzf then took 60% of the
-- float and drew its own frame inside Neovim's rounded border, leaving roughly
-- four in every ten lines blank with a doubled outline. Appending wins because
-- fzf honours the last occurrence of a flag.
appendFzfOpts("--height=100% --border=none")

---@param opts table The options for fuzzy logic.
function M.fuzzyLogic(opts)
  local win,buf = func.createWindow(opts.title, opts.ratio)
  local temp = vim.fn.stdpath("cache") .. "/opts_run"
  vim.api.nvim_set_option_value('bufhidden', 'wipe', {buf = buf})
  -- The redirect target must be quoted; stdpath("cache") sits under the home
  -- directory, which contains a space, so "> C:/Users/Mia Schionato/..." was
  -- read by the shell as "> C:/Users/Mia" and every picker failed at once.
  vim.cmd(string.format("terminal %s > %s", opts.cmd, vim.fn.shellescape(temp)))

  -- Arrows reach fzf as an escape sequence (<Esc>[A). On Windows the
  -- terminal can deliver it split when fzf is busy, fzf then reads a lone
  -- <Esc> and quits: the grep picker closed on the first arrow key. Its own
  -- one-byte keys for the same moves cannot be split.
  local term_opts = { buffer = buf, nowait = true }
  vim.keymap.set('t', '<Up>', '<C-k>', term_opts)
  vim.keymap.set('t', '<Down>', '<C-j>', term_opts)

  vim.api.nvim_create_autocmd("TermClose", {
    buffer = buf,
    callback = function()
      local data = ""

      if vim.fn.filereadable(temp) == 1 then
        local f = io.open(temp, "r")
        if f then
          local last_line = ""
          for line in f:lines() do
            last_line = line
          end
          f:close()
          os.remove(temp)
          data = last_line:gsub("%s+$", "")
        end
      end

      vim.schedule(function()
        if vim.api.nvim_win_is_valid(win) then vim.api.nvim_win_close(win, true) end
        if vim.api.nvim_buf_is_valid(buf) then vim.api.nvim_buf_delete(buf, { force = true }) end

        local function finish()
          if data ~= "" then
            opts.callback(data)
          elseif opts.on_cancel then
            -- Esc / Ctrl-C in fzf, or nothing matched.
            opts.on_cancel()
          end
        end

        -- Leave terminal mode before handing over. Closing the window does not,
        -- and neither does :stopinsert: Neovim stays in terminal mode until the
        -- next key arrives, so the callback ran with mode() still 't' and the
        -- first key typed afterwards was spent leaving that mode (an input()
        -- prompt opened from the callback could lose it, or be cancelled).
        -- Feed the key that leaves terminal mode, and run the callback once
        -- Neovim reports the mode change.
        if vim.api.nvim_get_mode().mode == "t" then
          vim.api.nvim_create_autocmd("ModeChanged", {
            pattern = "t:*",
            once = true,
            callback = function() vim.schedule(finish) end,
          })
          vim.api.nvim_feedkeys(vim.keycode("<C-\\><C-n>"), "n", false)
        else
          finish()
        end
      end)
    end
    })
  -- Enter terminal mode straight away, then once more on the next tick.
  --
  -- This used to be deferred by 50ms alone, which left the picker sitting in
  -- terminal-normal mode for that window. Arrow keys pressed in it hit the
  -- move-line mappings rather than fzf, so the first keystroke after opening a
  -- picker could be swallowed. The deferred call is kept as a second attempt in
  -- case something steals focus while the job starts.
  vim.cmd("startinsert")
  vim.defer_fn(function()
    if vim.api.nvim_get_current_buf() == buf and vim.api.nvim_get_mode().mode ~= "t" then
      vim.cmd("startinsert")
    end
  end, 50)
end

--- Pick one line of `lines` with fzf; `on_pick(line)` gets the choice and
--- `on_cancel()`, when given, runs if nothing was picked.
---
--- Five pickers (jumps, buffers, oldfiles, colorschemes, vim.ui.select) each
--- wrote their list to a fixed temp file and piped it into fzf by hand. The
--- file is now unique per call and always removed, picked or cancelled.
--- @param lines string[]
--- @param opts { title: string, ratio: number?, fzf: string? }  fzf: extra flags
local pick_count = 0
local function pickList(lines, opts, on_pick, on_cancel)
  pick_count = pick_count + 1
  local temp = vim.fn.stdpath("cache") .. "/pick_" .. pick_count
  vim.fn.writefile(lines, temp)
  M.fuzzyLogic({
    title = opts.title,
    ratio = opts.ratio or 0.7,
    cmd = string.format("cat %s | fzf %s", vim.fn.shellescape(temp), opts.fzf or ""),
    callback = function(selection)
      os.remove(temp)
      on_pick(selection)
    end,
    on_cancel = function()
      os.remove(temp)
      if on_cancel then on_cancel() end
    end,
  })
end

function M.fuzzySearch(path)
  if path == nil then path = vim.uv.os_homedir():gsub("\\", "/") .. "/" end
  path = asDir(path)
  local fd = "fd --hidden " .. fdExcludes() .. " --type file . --strip-cwd-prefix --base-directory  "
  local fzf = "fzf --keep-right --tiebreak=end"

  M.fuzzyLogic({
    title = "Fuzzy Search",
    ratio = 0.6,
    cmd = string.format("%s %s | %s", fd, vim.fn.shellescape(path), fzf),
    callback = function(selection)
      vim.cmd("edit! " .. vim.fn.fnameescape(path .. selection))
      vim.cmd("filetype detect")
    end

  })
end


--- Live grep: ripgrep runs again on every change of the query, and fzf only
--- shows its results. It used to pipe `rg .` into fzf -- every line of every
--- file under `path`, twice (the "." was given two times), all loaded before
--- the first key. Nothing is listed until something is typed.
function M.fuzzyGrep(path)
  path = asDir(path)
  local rg = "rg --column --line-number --no-heading --color=always --smart-case"
  -- fzf wants input on stdin even with --disabled; give it an empty one.
  -- By shell, not by OS: the windows branch runs these through Git bash.
  local empty = vim.o.shell:lower():match("cmd%.exe$") and "type nul" or "true"
  local fzf = "fzf --ansi --disabled --delimiter :"
    -- An empty query would match every line; list nothing instead. POSIX
    -- test: fzf runs reload through sh (Git bash on the windows branch).
    .. string.format(" --bind %s", vim.fn.shellescape("change:reload:[ -z {q} ] || " .. rg .. " -- {q}"))
    .. " --preview 'bat --style=numbers --color=always --highlight-line {2} {1}' --preview-window 'up,60\\%,border-bottom,+{2}+3/3'"

  M.fuzzyLogic({
    title = "Fuzzy Grep",
    ratio = 0.8,
    -- Run from inside `path` so ripgrep prints relative names. Given an
    -- absolute path its output starts with the drive letter, and fzf splitting
    -- on ":" then made {1} the bare "C" and {2} the path, so bat was handed a
    -- path where it wanted a line number. Counting fields from the end is not
    -- an option here, unlike fuzzyJump: the matched text can contain colons.
    cmd = string.format("cd %s && %s | %s", vim.fn.shellescape(path), empty, fzf),
    callback = function(selection)
      local rel, line, col = selection:match("^(.-):(%d+):(%d+)")
      if not (rel and line and col) then return end
      -- Those names are relative to the cd above, so rebuild the full one.
      local full_path = path .. (rel:gsub("^%.[/\\]", ""))
      vim.cmd("edit! " .. vim.fn.fnameescape(full_path))
      -- ripgrep's column is 1-based, the cursor's 0-based: without the -1
      -- the cursor landed one character right of the match.
      vim.api.nvim_win_set_cursor(0, {tonumber(line), tonumber(col) - 1})
      vim.cmd("filetype detect")
    end
  })
end

--- Neovim's help files, and every section of this config's own docs/ pages
--- ("pure todoist › Sync on …"): picking a section opens its page in a split
--- at that heading, drawn by mdview.
function M.fuzzyHelp()
  local entries, targets = {}, {}

  -- The one-file build (scripts/bundle.lua) unpacks them elsewhere.
  local docs = (vim.g.pure_bundle_dir or vim.fn.stdpath("config")) .. "/docs"
  for _, name in ipairs(vim.fn.isdirectory(docs) == 1 and vim.fn.readdir(docs) or {}) do
    local file = docs .. "/" .. name
    if name:match("%.md$") then
      local page = name == "README.md" and "index" or name:gsub("%.md$", "")
      local in_code = false
      for lnum, line in ipairs(vim.fn.readfile(file)) do
        -- Headings inside code blocks are examples, not sections.
        if line:match("^%s*```") then in_code = not in_code end
        local heading = not in_code and line:match("^#+%s+(.+)")
        if heading then
          local entry = ("pure %s › %s"):format(page, heading)
          if not targets[entry] then
            table.insert(entries, entry)
            targets[entry] = { file = file, lnum = lnum }
          end
        end
      end
    end
  end

  for _, name in ipairs(vim.fn.readdir(vim.fn.expand("$VIMRUNTIME/doc"))) do
    if name:match("%.txt$") then table.insert(entries, name) end
  end

  pickList(entries, { title = "Help" }, function(selection)
    local target = targets[selection]
    if not target then return vim.cmd("help " .. vim.fn.fnameescape(selection)) end
    vim.cmd("split " .. vim.fn.fnameescape(target.file))
    vim.api.nvim_win_set_cursor(0, { target.lnum, 0 })
    vim.cmd("normal! zt")
  end)
end

function M.fuzzyGit()
  local path = vim.fn.expand("%:p:h")

  local fzf = "fzf --ansi --preview 'git show --color=always {1}' --preview-window 'up,60\\%,wrap,border-bottom'"
  local git = "git log --oneline --color=always "

  M.fuzzyLogic({
    title = "Fuzzy Git log",
    ratio = 0.8,
    cmd = string.format("cd %s && %s | %s", vim.fn.shellescape(path), git, fzf),
    -- The selection is "abc1234 commit message"; it used to be passed to
    -- :edit, which opened an empty file named after the commit. Show the
    -- commit instead, in a scratch split (q closes it).
    callback = function (selection)
      local sha = selection:match("^(%x+)")
      if not sha then return end
      local out = vim.fn.systemlist({ "git", "-C", path, "show", "--stat", "--patch", sha })
      vim.cmd("botright new")
      local buf = vim.api.nvim_get_current_buf()
      vim.bo[buf].buftype = "nofile"
      vim.bo[buf].bufhidden = "wipe"
      vim.api.nvim_buf_set_lines(buf, 0, -1, false, out)
      vim.bo[buf].filetype = "git"
      vim.bo[buf].modifiable = false
      vim.keymap.set("n", "q", "<cmd>close<cr>", { buffer = buf })
    end
  })
end


function M.fuzzyGitGrep()
  local git_grep = "git grep --line-number --column"
  local fzf = "fzf --ansi --delimiter : --preview 'bat --style=numbers --color=always --highlight-line {2} {1}' --preview-window 'up,60\\%,border-bottom,+{2}+3/3'"
  -- Already cd's below, so git grep prints relative names and {1}/{2} line up.
  local path = asDir(vim.fn.expand("%:p:h"))

  M.fuzzyLogic({
    title = "Fuzzy Git Grep",
    ratio = 0.8,
    cmd = string.format("cd %s && %s . | %s", vim.fn.shellescape(path), git_grep, fzf),
    callback = function(selection)
      local rel, line, col_str = selection:match("^(.-):(%d+):(%d+)")
      if not rel then return end
      local col = tonumber(col_str)
      -- Relative to the cd above, so opening it as-is only worked when Neovim's
      -- own cwd happened to match. Rebuild the full name instead.
      local full_path = path .. (rel:gsub("^%.[/\\]", ""))

      vim.cmd("edit! " .. vim.fn.fnameescape(full_path))
      if line and col then
        vim.api.nvim_win_set_cursor(0, {tonumber(line), col - 1}) -- git grep's column is 1-based
      end
      vim.cmd("filetype detect")
    end
  })
end

function M.fuzzyJump()
  local jumps = {}
  for _, jump in ipairs(vim.fn.getjumplist()[1]) do
    local path = vim.api.nvim_buf_get_name(jump.bufnr)
    if path ~= "" then
      table.insert(jumps, string.format("%s:%d:%d", path, jump.lnum, jump.col))
    end
  end

  -- Fields are counted from the END. These lines are "path:line:col", and on
  -- Windows the path starts with a drive letter, so splitting on ":" made {1}
  -- the bare letter "C" and {2} the path -- which bat received where it wanted
  -- a line number, hence "[bat error]: invalid digit found in string".
  -- {-2} is the line and {1..-3} rejoins the whole path, drive letter included.
  pickList(jumps, {
    title = "fuzzy jumps",
    ratio = 0.8,
    fzf = "--ansi --delimiter : --preview 'bat --style=numbers --color=always --highlight-line {-2} {1..-3}' --preview-window 'up,60\\%,border-bottom,+{-2}+3/3'",
  }, function(selection)
    -- Windows paths start with a drive letter, so a '^([^:]+):' pattern would
    -- stop at the 'C:' colon; the lazy '.-' matches up to ':line:col'.
    local full_path, line, col = selection:match("^(.-):(%d+):(%d+)")
    if not full_path then return end
    vim.cmd("edit! " .. vim.fn.fnameescape(full_path))
    vim.api.nvim_win_set_cursor(0, { tonumber(line), tonumber(col) })
    vim.cmd("filetype detect")
  end)
end


function M.fuzzyBuffers()
  local buffers = {}
  for _, bufnr in ipairs(vim.api.nvim_list_bufs()) do
    local name = vim.api.nvim_buf_get_name(bufnr)
    if vim.api.nvim_buf_is_loaded(bufnr) and vim.bo[bufnr].buflisted and name ~= "" then
      table.insert(buffers, vim.fn.fnamemodify(name, ":."))
    end
  end
  pickList(buffers, { title = "Fuzzy buffers", fzf = "--keep-right --tiebreak=end" }, function(selection)
    vim.cmd("edit " .. vim.fn.fnameescape(selection))
    vim.cmd("filetype detect")
  end)
end

function M.fuzzyOldfiles()
  local oldfiles = vim.tbl_filter(function(f)
    return vim.fn.filereadable(f) == 1
  end, vim.v.oldfiles)
  pickList(oldfiles, { title = "Oldfiles" }, function(selection)
    vim.cmd("edit " .. vim.fn.fnameescape(selection))
    vim.cmd("filetype detect")
  end)
end

function M.fuzzyColorscheme()
  pickList(vim.fn.getcompletion("", "color"), { title = "Colorschemes" }, function(theme)
    vim.cmd("colorscheme " .. vim.fn.fnameescape(theme))
    vim.g.MY_THEME = theme
    if vim.g.neovide then
      vim.api.nvim_set_hl(0, 'Normal', { bg = "#060b1e" })
    end
  end)
end

function M.setup()
  vim.ui.select = function(items, opts, selected)
    opts = opts or {}
    if #items == 0 then
      selected(nil, nil)
      return
    end

    local choices = {}
    for i, item in ipairs(items) do -- Check if table or plain text
      if opts.format_item then
        choices[i] = opts.format_item(item)
      else
        choices[i] = tostring(item)
      end
    end

    -- on_choice(nil, nil) on cancel, as vim.ui.select promises.
    pickList(choices, { title = opts.prompt or "Select" }, function(selection)
      for i, choice in ipairs(choices) do
        if choice == selection then return selected(items[i], i) end
      end
      selected(nil, nil)
    end, function() selected(nil, nil) end)
  end

  vim.ui.input = function(opts, callback)
    opts = opts or {}
    local prompt = opts.prompt or "Input: "
    local win, buf = func.createWindow(prompt, 0.8)
    vim.api.nvim_win_set_height(win, 1)

    if opts.default then
      vim.api.nvim_buf_set_lines(buf, 0, -1, false, {opts.default})
      vim.cmd("startinsert!")
    end

    local confirmed = false

    local function submit()
      local lines = vim.api.nvim_buf_get_lines(buf, 0, -1, false)
      confirmed = true
      local input = table.concat(lines, "\n")
      vim.api.nvim_win_close(win, true)
      vim.api.nvim_buf_delete(buf, { force = true })
      callback(input)
    end

    local function cancel()
      -- Marked as handled before the buffer goes: deleting it fires the
      -- BufWipeout below, which called back with nil a second time.
      confirmed = true
      vim.api.nvim_win_close(win, true)
      vim.api.nvim_buf_delete(buf, { force = true })
      callback(nil)
    end

    local opts_map = {noremap = true, silent = true, nowait = true, buffer = buf}
    vim.keymap.set('i', '<CR>', submit, opts_map)
    vim.keymap.set('n', '<CR>', submit, opts_map)

    vim.keymap.set('n', 'q', cancel, opts_map)
    vim.keymap.set('n', '<Esc>', cancel, opts_map)

    vim.api.nvim_create_autocmd("BufWipeout", {
      buffer = buf,
      callback = function()
        if not confirmed then
          callback(nil)
        end
      end
    })


    vim.defer_fn(function()
        if vim.api.nvim_win_is_valid(win) then
            if opts.default then
                vim.cmd("startinsert!")
            else
                vim.cmd("startinsert")
            end
        end
    end, 10)
  end
end

function M.NewFile(path)
  path = asDir(path)
  local fd = "fd --hidden " .. fdExcludes() .. " --type directory . --strip-cwd-prefix --base-directory  "
  local fzf = "fzf --keep-right --tiebreak=end"
  M.fuzzyLogic({
    title = "Select New File Path",
    ratio = 0.6,
    cmd = string.format("%s %s | %s", fd, vim.fn.shellescape(path), fzf),
    callback = function(selection)
      vim.ui.input({prompt = "New file name: "}, function(input)
        if input and input ~= "" then
          vim.cmd("edit! " .. vim.fn.fnameescape(path .. selection .. "/" .. input))
        else
          -- was `path .. selection` .. "Untitled" -> ".../dirUntitled"
          vim.cmd("edit! " .. vim.fn.fnameescape(path .. selection .. "/Untitled"))
        end
      end)
    end
  })
end

function M.CompilerCommand()
  vim.ui.input({prompt = "Compiler Command:"}, function(input)
    if input and input ~= "" then
      terms.toggleTerminal(input, 0.6)
    end
  end)
end

---@param path string|nil The directory path to explore. If nil, uses current working directory.
function M.fuzzyExplorer(path)
  if path == nil then path = vim.fn.getcwd() end

  -- Use ls -ap to show hidden files and classify with indicators (/ for dirs)
  local list_cmd = "ls -ap --color=always " .. lsIgnores()

  -- Preview command for fzf. It's executed in `path` directory.
  -- Added --line-range to bat to avoid lagging on large files.
  -- POSIX 'if/then/fi'. This was fish syntax ("if ...; ...; else ...; end"),
  -- which the bash 'shell' set in init.lua rejects, so the preview pane only
  -- ever rendered a syntax error.
  local preview_cmd = "if [ -d {} ]; then ls -apF --color=always {}; else bat --color=always --style=numbers --line-range :500 {}; fi"
  local fzf_cmd = string.format("fzf --ansi --preview='%s' --print-query", preview_cmd)

  M.fuzzyLogic({
    title = "Explorer: " .. path,
    ratio = 0.8,
    cmd = string.format("cd %s && %s | %s", vim.fn.shellescape(path), list_cmd, fzf_cmd),
          callback = function(selection)
            if not selection or selection == "" or selection == "./" then
              return -- Do nothing
            end
    
            local new_path = vim.fn.resolve(path .. "/" .. selection)
    
            if selection:sub(-1) == '/' then
              -- User intends to create/enter a directory
              if vim.fn.isdirectory(new_path) == 0 then
                -- Directory doesn't exist, create it
                vim.fn.mkdir(new_path, "p")
              end
              -- Enter the directory
              M.fuzzyExplorer(new_path)
            else
              -- User intends to open/create a file
              if vim.fn.isdirectory(new_path) == 1 then
                -- It's an existing directory, but no trailing slash was typed
                -- so we enter it instead of trying to edit it as a file.
                M.fuzzyExplorer(new_path)
              else
                -- It's a file (new or existing)
                vim.cmd("edit! " .. vim.fn.fnameescape(new_path))
              end
            end
          end  })
end

return M


end

-- lua/pure/git.lua
package.preload["pure.git"] = function(...)
-- =============================================================================
--  Git
-- =============================================================================
--  Everyday git from inside Neovim, no plugins: git itself through
--  vim.system (no shell, so paths with spaces need no quoting on any OS).
--  Every command runs in the repository of the current file.
--
--  The status buffer (M.status) lists staged, unstaged and untracked files;
--  keys act on the file under the cursor:
--    a  stage        u  unstage       r  discard changes (asks first)
--    d  diff         <CR> open file   c  commit        p  push
--    R  refresh      q / <Esc> close
-- =============================================================================

local M = {}

-- -----------------------------------------------------------------------------
--  Running git
-- -----------------------------------------------------------------------------

--- Directory to run git from: the current file's, or the cwd for buffers
--- that are not files (the status buffer keeps its repository in b:pure_git_root).
local function startDir()
  if vim.b.pure_git_root then return vim.b.pure_git_root end
  local name = vim.api.nvim_buf_get_name(0)
  if name ~= '' and vim.bo.buftype == '' then return vim.fs.dirname(name) end
  return vim.fn.getcwd()
end

--- Top level of the repository containing `dir`, or nil.
local function repoRoot(dir)
  local res = vim.system({ 'git', '-C', dir, 'rev-parse', '--show-toplevel' }, { text = true }):wait()
  if res.code ~= 0 then return nil end
  return vim.fs.normalize(vim.trim(res.stdout))
end

--- Run `git <args>` in `root`; `cb(ok, output)` on the main loop.
--- Without a callback it reports the result as a notification.
local function git(root, args, cb)
  local cmd = vim.list_extend({ 'git', '-C', root }, args)
  vim.system(cmd, { text = true }, vim.schedule_wrap(function(res)
    local out = vim.trim((res.stdout or '') .. '\n' .. (res.stderr or ''))
    if cb then return cb(res.code == 0, out) end
    local level = res.code == 0 and vim.log.levels.INFO or vim.log.levels.ERROR
    vim.notify('git ' .. args[1] .. (out ~= '' and (':\n' .. out) or ' done'), level)
  end))
end

--- The repository root and the current file relative to it, or nil + a message.
local function currentFile()
  local root = repoRoot(startDir())
  if not root then return nil, 'Not inside a git repository' end
  local name = vim.fs.normalize(vim.api.nvim_buf_get_name(0))
  if name == '' or vim.bo.buftype ~= '' then return nil, 'No file in this buffer' end
  -- Plain prefix strip: the path may contain '-', '.' or spaces. Case-blind
  -- on Windows, where git may print C:/ for a buffer named c:/ (same file).
  local prefix = name:sub(1, #root + 1)
  local same = vim.fn.has('win32') == 1 and prefix:lower() == (root .. '/'):lower() or prefix == root .. '/'
  if not same then return nil, 'File is outside ' .. root end
  return root, name:sub(#root + 2)
end

--- Reload buffers whose files git just changed (restore, pull, switch).
local function reloadBuffers()
  vim.cmd('checktime')
end

-- -----------------------------------------------------------------------------
--  Single-file and repository commands
-- -----------------------------------------------------------------------------

function M.addFile()
  local root, file = currentFile()
  if not root then return vim.notify(file, vim.log.levels.WARN) end
  git(root, { 'add', '--', file }, function(ok, out)
    vim.notify(ok and ('Staged ' .. file) or out, ok and vim.log.levels.INFO or vim.log.levels.ERROR)
  end)
end

function M.addAll()
  local root = repoRoot(startDir())
  if not root then return vim.notify('Not inside a git repository', vim.log.levels.WARN) end
  git(root, { 'add', '-A' }, function(ok, out)
    vim.notify(ok and 'Staged all changes' or out, ok and vim.log.levels.INFO or vim.log.levels.ERROR)
  end)
end

function M.unstageFile()
  local root, file = currentFile()
  if not root then return vim.notify(file, vim.log.levels.WARN) end
  git(root, { 'restore', '--staged', '--', file }, function(ok, out)
    vim.notify(ok and ('Unstaged ' .. file) or out, ok and vim.log.levels.INFO or vim.log.levels.ERROR)
  end)
end

--- Discard the working-tree changes of `file`. Asks first: they are gone for
--- good, git keeps no copy of uncommitted edits.
local function restore(root, file, done)
  if vim.fn.confirm('Discard all uncommitted changes to ' .. file .. '?', '&Discard\n&Cancel', 2) ~= 1 then
    return
  end
  git(root, { 'restore', '--', file }, function(ok, out)
    vim.notify(ok and ('Restored ' .. file) or out, ok and vim.log.levels.INFO or vim.log.levels.ERROR)
    reloadBuffers()
    if done then done() end
  end)
end

function M.restoreFile()
  local root, file = currentFile()
  if not root then return vim.notify(file, vim.log.levels.WARN) end
  restore(root, file)
end

--- Commit what is staged, asking for the message.
function M.commit(done)
  local root = repoRoot(startDir())
  if not root then return vim.notify('Not inside a git repository', vim.log.levels.WARN) end
  local ok, msg = pcall(vim.fn.input, 'Commit message: ')
  if not ok or vim.trim(msg) == '' then return vim.notify('Commit cancelled') end
  git(root, { 'commit', '-m', msg }, function(success, out)
    -- First line is enough: "[branch abc123] message".
    vim.notify(success and out:match('^[^\n]*') or out, success and vim.log.levels.INFO or vim.log.levels.ERROR)
    if done then done() end
  end)
end

function M.push()
  local root = repoRoot(startDir())
  if not root then return vim.notify('Not inside a git repository', vim.log.levels.WARN) end
  vim.notify('git push…')
  git(root, { 'push' })
end

function M.pull()
  local root = repoRoot(startDir())
  if not root then return vim.notify('Not inside a git repository', vim.log.levels.WARN) end
  vim.notify('git pull…')
  git(root, { 'pull' }, function(ok, out)
    vim.notify('git pull:\n' .. out, ok and vim.log.levels.INFO or vim.log.levels.ERROR)
    reloadBuffers()
  end)
end

--- Who last changed the cursor line, when, and in which commit.
function M.blameLine()
  local root, file = currentFile()
  if not root then return vim.notify(file, vim.log.levels.WARN) end
  local lnum = vim.fn.line('.')
  git(root, { 'blame', '-L', lnum .. ',' .. lnum, '--porcelain', '--', file }, function(ok, out)
    if not ok then return vim.notify(out, vim.log.levels.ERROR) end
    local sha = out:match('^(%x+)')
    if sha and sha:match('^0+$') then return vim.notify('Line ' .. lnum .. ': not committed yet') end
    local author = out:match('\nauthor (.-)\n') or '?'
    local time = tonumber(out:match('\nauthor%-time (%d+)')) or 0
    local summary = out:match('\nsummary (.-)\n') or ''
    vim.notify(('%s  %s, %s\n%s'):format(sha and sha:sub(1, 7) or '?', author, os.date('%Y-%m-%d', time), summary))
  end)
end

--- Pick a local branch and switch to it.
function M.switchBranch()
  local root = repoRoot(startDir())
  if not root then return vim.notify('Not inside a git repository', vim.log.levels.WARN) end
  git(root, { 'branch', '--format=%(refname:short)' }, function(ok, out)
    if not ok then return vim.notify(out, vim.log.levels.ERROR) end
    local branches = vim.split(out, '\n', { trimempty = true })
    vim.ui.select(branches, { prompt = 'Switch to branch' }, function(branch)
      if not branch then return end
      git(root, { 'switch', branch }, function(sok, sout)
        -- git refuses when local edits would be overwritten; its message says which.
        vim.notify(sok and ('On ' .. branch) or sout, sok and vim.log.levels.INFO or vim.log.levels.ERROR)
        reloadBuffers()
      end)
    end)
  end)
end

-- -----------------------------------------------------------------------------
--  Status buffer
-- -----------------------------------------------------------------------------

local status = { buf = nil, root = nil, rows = {} } -- rows: line number -> { file, section }

--- Parse `git status --porcelain=v1 -b` into the branch line and three lists.
local function parseStatus(out)
  local branch, staged, changed, untracked = '', {}, {}, {}
  for _, line in ipairs(vim.split(out, '\n', { trimempty = true })) do
    if line:sub(1, 2) == '##' then
      branch = line:sub(4)
    else
      local x, y, path = line:sub(1, 1), line:sub(2, 2), line:sub(4)
      -- A rename reads "old -> new"; the new name is the file that exists.
      path = path:match('%-> (.+)$') or path
      path = path:match('^"(.*)"$') or path
      if x == '?' then
        table.insert(untracked, { code = '??', file = path })
      else
        if x ~= ' ' then table.insert(staged, { code = x, file = path }) end
        if y ~= ' ' then table.insert(changed, { code = y, file = path }) end
      end
    end
  end
  return branch, staged, changed, untracked
end

local function refresh()
  if not (status.buf and vim.api.nvim_buf_is_valid(status.buf)) then return end
  git(status.root, { 'status', '--porcelain=v1', '-b' }, function(ok, out)
    if not vim.api.nvim_buf_is_valid(status.buf) then return end
    local lines, rows = {}, {}
    if not ok then
      lines = { '# Git', '', out }
    else
      local branch, staged, changed, untracked = parseStatus(out)
      lines = { '# Git — ' .. branch, '' }
      local function section(title, list, kind)
        if #list == 0 then return end
        table.insert(lines, '## ' .. title)
        for _, e in ipairs(list) do
          table.insert(lines, e.code .. '  ' .. e.file)
          rows[#lines] = { file = e.file, section = kind }
        end
        table.insert(lines, '')
      end
      section('Staged', staged, 'staged')
      section('Changes', changed, 'changed')
      section('Untracked', untracked, 'untracked')
      if #staged + #changed + #untracked == 0 then table.insert(lines, 'Nothing to commit, working tree clean.') end
      table.insert(lines, 'a stage · u unstage · r discard · d diff · <CR> open · c commit · p push · R refresh · q close')
    end
    status.rows = rows
    vim.bo[status.buf].modifiable = true
    vim.api.nvim_buf_set_lines(status.buf, 0, -1, false, lines)
    vim.bo[status.buf].modifiable = false
  end)
end

local function entry()
  return status.rows[vim.fn.line('.')]
end

--- Run `git <args> -- <file>` for the entry under the cursor, then refresh.
local function onEntry(args, fn)
  return function()
    local e = entry()
    if not e then return end
    if fn then return fn(e) end
    git(status.root, vim.list_extend(vim.deepcopy(args), { '--', e.file }), function(ok, out)
      if not ok then vim.notify(out, vim.log.levels.ERROR) end
      refresh()
    end)
  end
end

--- Diff of one entry in a split: staged changes for staged entries, working
--- changes otherwise; an untracked file is shown whole.
local function showDiff(e)
  local args = e.section == 'staged' and { 'diff', '--cached', '--', e.file }
    or e.section == 'untracked' and { 'diff', '--no-index', '--', '/dev/null', e.file }
    or { 'diff', '--', e.file }
  git(status.root, args, function(_, out)
    -- --no-index exits 1 when the files differ, which is always here.
    vim.cmd('botright new')
    local buf = vim.api.nvim_get_current_buf()
    vim.bo[buf].buftype = 'nofile'
    vim.bo[buf].bufhidden = 'wipe'
    vim.api.nvim_buf_set_lines(buf, 0, -1, false, vim.split(out, '\n'))
    vim.bo[buf].filetype = 'diff'
    vim.bo[buf].modifiable = false
    vim.keymap.set('n', 'q', '<cmd>close<cr>', { buffer = buf })
  end)
end

function M.status()
  local root = repoRoot(startDir())
  if not root then return vim.notify('Not inside a git repository', vim.log.levels.WARN) end
  status.root = root

  if not (status.buf and vim.api.nvim_buf_is_valid(status.buf)) then
    local buf = vim.api.nvim_create_buf(false, true)
    status.buf = buf
    vim.bo[buf].bufhidden = 'hide'
    pcall(vim.api.nvim_buf_set_name, buf, 'git://status')
    vim.b[buf].pure_mdview = true -- let mdview draw the ## headings
    vim.bo[buf].filetype = 'markdown'

    local map = function(lhs, fn, desc) vim.keymap.set('n', lhs, fn, { buffer = buf, desc = desc }) end
    map('a', onEntry({ 'add' }), 'Stage file')
    map('u', onEntry({ 'restore', '--staged' }), 'Unstage file')
    map('r', onEntry(nil, function(e)
      if e.section == 'untracked' then
        return vim.notify('Untracked file: delete it yourself if you mean to', vim.log.levels.WARN)
      end
      restore(status.root, e.file, refresh)
    end), 'Discard changes')
    map('d', onEntry(nil, showDiff), 'Show diff')
    map('<CR>', onEntry(nil, function(e)
      vim.cmd('wincmd p')
      vim.cmd('edit ' .. vim.fn.fnameescape(status.root .. '/' .. e.file))
    end), 'Open file')
    map('c', function() M.commit(refresh) end, 'Commit')
    map('p', M.push, 'Push')
    map('R', refresh, 'Refresh')
    map('q', '<cmd>close<cr>', 'Close')
    map('<Esc>', '<cmd>close<cr>', 'Close')
  end
  vim.b[status.buf].pure_git_root = root

  local win = vim.fn.bufwinid(status.buf)
  if win ~= -1 then
    vim.api.nvim_set_current_win(win)
  else
    vim.cmd('botright split')
    vim.api.nvim_win_set_buf(0, status.buf)
  end
  vim.wo.spell = false
  refresh()
end

return M

end

-- lua/pure/indentscope.lua
package.preload["pure.indentscope"] = function(...)
-- =============================================================================
--  Indent scope
-- =============================================================================
--  Replaces mini.indentscope. Draws a vertical line beside the indented block
--  the cursor is in, and adds a text object and motions for that block:
--
--    ii / ai   inner scope (the block) / outer scope (plus the lines around it)
--    [i / ]i   jump to the line above / below the block
--
--  A "scope" is the run of lines around the cursor whose indent is at least
--  the reference indent. Blank lines never end it, so a block with an empty
--  line in the middle stays one scope. The first line above and below with a
--  smaller indent are its borders ("if x then" / "end").
--
--  Colour: PureIndentscopeSymbol (links to Delimiter unless a theme sets it).
--  Disable in a buffer with  vim.b.pure_indentscope_disable = true
-- =============================================================================

local M = {}

local symbol = '╎'
local delay = 100       -- ms after the last cursor move before redrawing
local max_lines = 10000 -- stop scanning this far from the cursor

local ns = vim.api.nvim_create_namespace('pure_indentscope')
local timer = assert(vim.uv.new_timer())
local drawn_buf = nil   -- the buffer holding the current marks, to clear it

vim.api.nvim_set_hl(0, 'PureIndentscopeSymbol', { link = 'Delimiter', default = true })

local function isBlank(lnum)
  return vim.fn.getline(lnum):match('^%s*$') ~= nil
end

--- Indent the scope is measured against.
---
--- On a blank line the line itself says nothing, so the deeper of its two
--- neighbours is used: an empty line inside a block belongs to that block.
---
--- On other lines the cursor column caps it (mini's indent_at_cursor): with
--- the cursor inside the leading whitespace, moving left selects wider and
--- wider scopes. Not on blank lines, where the cursor always sits in column 0
--- and the cap would always pick the outermost scope.
local function referenceIndent(lnum)
  if isBlank(lnum) then
    local prev = vim.fn.prevnonblank(lnum)
    local next = vim.fn.nextnonblank(lnum)
    return math.max(prev > 0 and vim.fn.indent(prev) or 0, next > 0 and vim.fn.indent(next) or 0)
  end
  return math.min(vim.fn.indent(lnum), vim.fn.virtcol('.'))
end

--- Scope around `lnum`, or nil when the cursor is not inside an indented block.
--- @return { top: integer, bottom: integer, border_top: integer?, border_bottom: integer?, col: integer }?
function M.getScope(lnum)
  lnum = lnum or vim.fn.line('.')
  local ref = referenceIndent(lnum)
  -- Indent 0 means the whole file: nothing to draw and no borders to jump to.
  if ref <= 0 then return nil end

  local last = vim.fn.line('$')
  local function inside(l)
    return isBlank(l) or vim.fn.indent(l) >= ref
  end

  local top = lnum
  while top > 1 and lnum - top < max_lines and inside(top - 1) do
    top = top - 1
  end
  local bottom = lnum
  while bottom < last and bottom - lnum < max_lines and inside(bottom + 1) do
    bottom = bottom + 1
  end

  -- Blank lines at either edge sit between blocks, not inside this one.
  while top < bottom and isBlank(top) do top = top + 1 end
  while bottom > top and isBlank(bottom) do bottom = bottom - 1 end

  local border_top = top > 1 and top - 1 or nil
  local border_bottom = bottom < last and bottom + 1 or nil

  -- The line is drawn in the column where the borders start, i.e. inside the
  -- body's leading whitespace. Without borders (a block at the very top of the
  -- file) fall back to one step left of the body.
  local col
  if border_top or border_bottom then
    col = math.max(border_top and vim.fn.indent(border_top) or 0,
      border_bottom and vim.fn.indent(border_bottom) or 0)
  else
    col = math.max(ref - vim.fn.shiftwidth(), 0)
  end

  return { top = top, bottom = bottom, border_top = border_top, border_bottom = border_bottom, col = col }
end

-- -----------------------------------------------------------------------------
--  Drawing
-- -----------------------------------------------------------------------------
local function clear()
  if drawn_buf and vim.api.nvim_buf_is_valid(drawn_buf) then
    vim.api.nvim_buf_clear_namespace(drawn_buf, ns, 0, -1)
  end
  drawn_buf = nil
end

local function enabled(buf)
  -- buftype ~= '' skips terminals, help, oil, the dashboard, quickfix, ...
  return vim.bo[buf].buftype == ''
    and not vim.b[buf].pure_indentscope_disable
    and not vim.g.pure_indentscope_disable
end

local function draw()
  clear()
  local buf = vim.api.nvim_get_current_buf()
  if not enabled(buf) then return end

  local scope = M.getScope()
  if not scope then return end

  -- Only the visible part needs marks, so a long block costs no more than a
  -- screenful. Horizontal scroll moves the column the line has to be drawn at.
  local leftcol = vim.fn.winsaveview().leftcol
  local win_col = scope.col - leftcol
  if win_col < 0 then return end

  local first = math.max(scope.top, vim.fn.line('w0'))
  local last = math.min(scope.bottom, vim.fn.line('w$'))
  for lnum = first, last do
    -- Skip lines whose text starts at or before that column (a line inside a
    -- string, for instance); drawing there would cover real characters.
    if isBlank(lnum) or vim.fn.indent(lnum) > scope.col then
      vim.api.nvim_buf_set_extmark(buf, ns, lnum - 1, 0, {
        virt_text = { { symbol, 'PureIndentscopeSymbol' } },
        virt_text_win_col = win_col,
        hl_mode = 'combine',
        priority = 2,
      })
    end
  end
  drawn_buf = buf
end

--- Redraw after `delay` ms without movement, so holding j does not redraw on
--- every line.
local function schedule()
  timer:stop()
  timer:start(delay, 0, vim.schedule_wrap(draw))
end

vim.api.nvim_create_autocmd(
  { 'CursorMoved', 'CursorMovedI', 'TextChanged', 'TextChangedI', 'WinScrolled', 'BufWinEnter' }, {
    group = vim.api.nvim_create_augroup('PureIndentscope', { clear = true }),
    callback = schedule,
  })

-- Leaving a window clears straight away, otherwise the line stays behind in
-- the window you just left.
vim.api.nvim_create_autocmd({ 'WinLeave', 'BufLeave' }, {
  group = 'PureIndentscope',
  callback = function()
    timer:stop()
    clear()
  end,
})

-- -----------------------------------------------------------------------------
--  Text objects and motions
-- -----------------------------------------------------------------------------

--- Select the scope linewise. `outer` includes the border lines.
---
--- Mapped through ':<C-u>' rather than <Cmd>: the ':' leaves visual mode (and
--- keeps a pending operator waiting), so the 'V' below becomes the selection
--- the operator acts on -- dii, yai and vii all work the same way.
function M.textobject(outer)
  local scope = M.getScope()
  if not scope then return end
  local top = outer and scope.border_top or scope.top
  local bottom = outer and scope.border_bottom or scope.bottom
  vim.cmd(('normal! %dGV%dG'):format(top, bottom))
end

--- Keys that jump to the line above (`up`) or below the scope.
---
--- Returned from an expr mapping as '{lnum}G', so the jump lands in the
--- jumplist like any G. With an operator pending, a leading 'V' makes it
--- linewise: d]i deletes whole lines down to the border.
local function jump(up)
  return function()
    local scope = M.getScope()
    if not scope then return '' end
    local target = up and (scope.border_top or scope.top) or (scope.border_bottom or scope.bottom)
    local linewise = vim.fn.mode(1):sub(1, 2) == 'no' and 'V' or ''
    return linewise .. target .. 'G'
  end
end

vim.keymap.set({ 'x', 'o' }, 'ii', ':<C-u>lua require("pure.indentscope").textobject(false)<CR>',
  { silent = true, desc = 'Inner indent scope' })
vim.keymap.set({ 'x', 'o' }, 'ai', ':<C-u>lua require("pure.indentscope").textobject(true)<CR>',
  { silent = true, desc = 'Outer indent scope' })
vim.keymap.set({ 'n', 'x', 'o' }, '[i', jump(true), { expr = true, desc = 'Indent scope top' })
vim.keymap.set({ 'n', 'x', 'o' }, ']i', jump(false), { expr = true, desc = 'Indent scope bottom' })

return M

end

-- lua/pure/keyhint.lua
package.preload["pure.keyhint"] = function(...)
-- =============================================================================
--  Key hints  (a pure Lua take on which-key)
-- =============================================================================
--  Press <leader> and wait: a window at the bottom lists every key that can
--  come next, with the mapping's description, and names the groups
--  (<leader>f -> Find). Keep typing and it narrows down.
--
--  How it works: <leader> is a buffer-local <nowait> mapping (the "trigger"),
--  so it fires at once. It then reads the next keys itself with getcharstr(),
--  opening the window when nothing is typed for a while. Once the keys name
--  exactly one mapping, the trigger is removed for a moment and the keys are
--  typed again, so the real mapping runs just as if the hint window had never
--  been there. Typed quickly, nothing is shown and nothing is slower.
--
--  While it waits:  <BS> one key back   <Esc> cancel
--                   <CR> run the mapping typed so far, when a longer one
--                        shares its keys
--
--  Settings (configs.lua / keymaps.lua):
--    vim.g.pure_keyhint_delay     ms before the window shows (default 1000)
--    vim.g.pure_keyhint_groups    { ['<leader>f'] = 'Find', ... }
--    vim.g.pure_keyhint_triggers  { { 'n', '<leader>' }, { 'x', '<leader>' } }
--    vim.g.pure_keyhint = false   turns it off
-- =============================================================================

local M = {}
local api = vim.api

local ESC, BS, CR = vim.keycode('<Esc>'), vim.keycode('<BS>'), vim.keycode('<CR>')
local ns = api.nvim_create_namespace('pure_keyhint')

-- Linked, so the window follows the colorscheme.
local function setHighlights()
  local links = {
    PureHintKey = 'Function',
    PureHintGroup = 'Keyword',
    PureHintDesc = 'NormalFloat',
    PureHintSep = 'Comment',
  }
  for name, target in pairs(links) do
    api.nvim_set_hl(0, name, { link = target, default = true })
  end
end

local function triggers()
  return vim.g.pure_keyhint_triggers or { { 'n', '<leader>' }, { 'x', '<leader>' } }
end

--- The first key of raw key bytes: one character, or a 3-byte special key
--- (<BS>, <F1>, ...), with its modifier prefix if it has one (<M-x>).
local function firstKey(s)
  if s:byte(1) == 0x80 then
    if s:byte(2) == 0xfc then return s:sub(1, 3) .. firstKey(s:sub(4)) end
    return s:sub(1, 3)
  end
  return vim.fn.strcharpart(s, 0, 1)
end

--- Truncate to a display width, ending in '…' when cut.
local function fit(s, width)
  if vim.fn.strdisplaywidth(s) <= width then return s end
  local out = ''
  for _, ch in ipairs(vim.fn.split(s, [[\zs]])) do
    if vim.fn.strdisplaywidth(out .. ch) >= width then break end
    out = out .. ch
  end
  return out .. '…'
end

--- Every mapping of `mode` whose keys start with `prefix` (or are `prefix`),
--- by raw keys, leaving out the bare trigger. Buffer-local ones are read
--- last, so they win over a global one, as they do when typed.
local function mappingsFrom(mode, prefix, trigger)
  local found = {}
  local function add(list)
    for _, m in ipairs(list) do
      local raw = m.lhsraw or vim.keycode(m.lhs)
      if raw ~= trigger and raw:sub(1, #prefix) == prefix then found[raw] = m end
    end
  end
  add(api.nvim_get_keymap(mode))
  add(api.nvim_buf_get_keymap(0, mode))
  return found
end

--- Group names from vim.g.pure_keyhint_groups, keyed by raw keys.
local function groupNames()
  local names = {}
  for keys, name in pairs(vim.g.pure_keyhint_groups or {}) do
    names[vim.keycode(keys)] = name
  end
  return names
end

-- -----------------------------------------------------------------------------
--  Window
-- -----------------------------------------------------------------------------

--- One entry per key that can follow `keys`: a mapping or a group of them.
local function entries(maps, keys)
  local by_key = {}
  for raw, m in pairs(maps) do
    if raw ~= keys then
      local k = firstKey(raw:sub(#keys + 1))
      local e = by_key[k] or { key = k, label = vim.fn.keytrans(k), count = 0 }
      e.count = e.count + 1
      if raw == keys .. k then e.map = m end
      e.any = m
      by_key[k] = e
    end
  end

  local names = groupNames()
  local list = {}
  for k, e in pairs(by_key) do
    if e.count == 1 and e.map then
      e.desc = e.map.desc or e.map.rhs or 'Lua function'
    else
      e.group = true
      -- Unnamed: a lone mapping lends its description, else the count.
      e.desc = '+' .. (names[keys .. k]
        or (e.count == 1 and e.any.desc) or (e.count .. ' keymaps'))
    end
    table.insert(list, e)
  end
  -- Alphabetical, lowercase before uppercase (a A b B ...).
  table.sort(list, function(a, b)
    local la, lb = a.label:lower(), b.label:lower()
    if la ~= lb then return la < lb end
    return a.label > b.label
  end)
  return list
end

local view = { buf = nil, win = nil }

local function close()
  if view.win and api.nvim_win_is_valid(view.win) then api.nvim_win_close(view.win, true) end
  view.win = nil
end

--- Draw the hints for `keys` in columns across the bottom of the screen.
local function show(maps, keys)
  local list = entries(maps, keys)
  local width = math.max(20, vim.o.columns - 2) -- minus the border

  local key_w, cell_w = 1, 10
  for _, e in ipairs(list) do key_w = math.max(key_w, vim.fn.strdisplaywidth(e.label)) end
  for _, e in ipairs(list) do
    cell_w = math.max(cell_w, key_w + 3 + vim.fn.strdisplaywidth(e.desc))
  end
  cell_w = math.min(cell_w, 40, width)
  local gap = 3
  local ncols = math.max(1, math.floor((width + gap) / (cell_w + gap)))
  local max_rows = math.max(1, math.floor(vim.o.lines * 0.4))
  local nrows = math.min(math.ceil(#list / ncols), max_rows)

  -- Column by column, so each column reads down in order.
  local lines, marks = {}, {}
  for r = 1, nrows do
    local line = ''
    for c = 0, ncols - 1 do
      local e = list[c * nrows + r]
      if e then
        if c > 0 then line = line .. string.rep(' ', gap) end
        local label = e.label .. string.rep(' ', key_w - vim.fn.strdisplaywidth(e.label))
        local desc = fit(e.desc, cell_w - key_w - 3)
        local cell = label .. ' → ' .. desc
        local start = #line
        table.insert(marks, { r - 1, start, start + #label, 'PureHintKey' })
        table.insert(marks, { r - 1, start + #label, start + #label + #' → ', 'PureHintSep' })
        table.insert(marks, { r - 1, start + #label + #' → ', start + #cell,
          e.group and 'PureHintGroup' or 'PureHintDesc' })
        line = line .. cell .. string.rep(' ', cell_w - vim.fn.strdisplaywidth(cell))
      end
    end
    lines[r] = ' ' .. line
  end
  if #list > nrows * ncols then
    lines[nrows] = lines[nrows]:gsub('%s*$', '') .. '  …'
  end

  if not (view.buf and api.nvim_buf_is_valid(view.buf)) then
    view.buf = api.nvim_create_buf(false, true)
    vim.bo[view.buf].bufhidden = 'hide'
  end
  api.nvim_buf_set_lines(view.buf, 0, -1, false, lines)
  api.nvim_buf_clear_namespace(view.buf, ns, 0, -1)
  for _, m in ipairs(marks) do
    -- +1: every line starts with one space of padding.
    api.nvim_buf_set_extmark(view.buf, ns, m[1], m[2] + 1, { end_col = m[3] + 1, hl_group = m[4] })
  end

  local name = groupNames()[keys]
  local title = ' ' .. vim.fn.keytrans(keys) .. (name and ('  ' .. name) or '') .. ' '
  local statusline = vim.o.laststatus > 0 and 1 or 0
  local config = {
    relative = 'editor',
    row = math.max(0, vim.o.lines - vim.o.cmdheight - statusline - nrows - 2),
    col = 0,
    width = width,
    height = nrows,
    title = title,
    title_pos = 'left',
    style = 'minimal',
    focusable = false,
    zindex = 250,
  }
  if view.win and api.nvim_win_is_valid(view.win) then
    api.nvim_win_set_config(view.win, config)
  else
    config.noautocmd = true
    view.win = api.nvim_open_win(view.buf, false, config)
  end
  vim.cmd.redraw()
end

-- -----------------------------------------------------------------------------
--  Triggers
-- -----------------------------------------------------------------------------

local query

local function mapTriggers(buf)
  if vim.g.pure_keyhint == false or not api.nvim_buf_is_valid(buf) then return end
  for _, t in ipairs(triggers()) do
    vim.keymap.set(t[1], t[2], function() query(t[1], t[2]) end,
      { buffer = buf, nowait = true, desc = 'Key hints' })
  end
end

local function unmapTriggers(buf, mode)
  for _, t in ipairs(triggers()) do
    if t[1] == mode then pcall(vim.keymap.del, mode, t[2], { buffer = buf }) end
  end
end

--- The register v:register holds when none was typed.
local function defaultRegister()
  local cb = vim.o.clipboard
  if cb:find('unnamedplus') then return '+' end
  if cb:find('unnamed') then return '*' end
  return '"'
end

--- Type `keys` again with the trigger out of the way, so the real mapping
--- runs. The count and register typed before the trigger go in front.
local function run(buf, mode, keys, count, register)
  unmapTriggers(buf, mode)
  local prefix = register ~= defaultRegister() and ('"' .. register) or ''
  if count > 0 then prefix = prefix .. count end
  -- 'm' remaps, 'i' puts the keys before anything typed meanwhile. Not 't':
  -- the keys were already typed once (and recorded, in a macro).
  api.nvim_feedkeys(prefix .. keys, 'mi', false)
  -- Runs after the keys above were consumed.
  vim.schedule(function() mapTriggers(buf) end)
end

local generation = 0

query = function(mode, trigger)
  local buf = api.nvim_get_current_buf()
  local count, register = vim.v.count, vim.v.register
  local start = vim.keycode(trigger)
  local typed = {}
  local shown, timer = false, nil
  local result
  -- showcmd would print the trigger's Lua callback ("~@<fd>") in the
  -- statusline for as long as this waits; the window title shows the keys.
  local showcmd = vim.o.showcmd
  vim.o.showcmd = false

  while true do
    local keys = start .. table.concat(typed)
    local maps = mappingsFrom(mode, keys, start)
    local exact = maps[keys]
    local longer = vim.tbl_count(maps) > (exact and 1 or 0)

    if exact and not longer then result = keys break end
    if not longer then break end -- nothing is mapped to these keys: drop them

    generation = generation + 1
    if shown then
      show(maps, keys)
    else
      local gen = generation
      timer = vim.uv.new_timer()
      timer:start(vim.g.pure_keyhint_delay or 1000, 0, vim.schedule_wrap(function()
        -- getcharstr() may have returned in the meantime.
        if gen ~= generation then return end
        shown = true
        show(maps, keys)
      end))
    end

    local ok, ch = pcall(vim.fn.getcharstr)
    generation = generation + 1
    if timer then
      timer:stop()
      timer:close()
      timer = nil
    end

    if not ok or ch == ESC then break end
    if ch == BS then
      if #typed == 0 then break end
      table.remove(typed)
    elseif ch == CR and exact then
      result = keys
      break
    else
      table.insert(typed, ch)
    end
  end

  close()
  vim.o.showcmd = showcmd
  if result then run(buf, mode, result, count, register) end
end

-- -----------------------------------------------------------------------------
--  Setup
-- -----------------------------------------------------------------------------

setHighlights()
local group = api.nvim_create_augroup('PureKeyhint', { clear = true })
api.nvim_create_autocmd('ColorScheme', { group = group, callback = setHighlights })
api.nvim_create_autocmd('BufEnter', {
  group = group,
  callback = function(args) mapTriggers(args.buf) end,
})
for _, buf in ipairs(api.nvim_list_bufs()) do
  if api.nvim_buf_is_loaded(buf) then mapTriggers(buf) end
end

return M

end

-- lua/pure/mdview.lua
package.preload["pure.mdview"] = function(...)
-- =============================================================================
--  Markdown view
-- =============================================================================
--  Renders markdown in place, the way render-markdown.nvim does: the text is
--  never changed, extmarks draw over it (the same mechanism as the git diff
--  toggle in configs/functions.lua). Treesitter says what each piece is, so a
--  '-' inside a code block is never mistaken for a bullet.
--
--    # Heading         icon over the #s, coloured band across the line
--    - item            bullet per nesting level (● ○ ◆ ◇)
--    - [ ] / - [x]     checkbox icons; done items are dimmed
--    > quote           bar instead of '>'
--    ---               full-width line
--    | tables |        box-drawing borders
--    ```lang           shaded block with the language as a label
--    `code`            shaded background
--    ---               the frontmatter (Obsidian's properties) is hidden
--    key: value
--    ---
--    [^1]: note        footnote definitions are hidden
--    text[^1]          footnote references show as a superscript: text¹
--    [[path/note|Text]]  wikilinks show only their text: Text
--    [[note#Section]]    ... or the note (and section): note > Section
--    ![[image.png]]      embeds get an icon: image or file
--    ```todoist          the query is hidden; pure/todoist.lua draws the tasks
--
--  Everything is drawn with 'overlay' virtual text of the same width as what
--  it covers, so columns never shift and the cursor lands where the real
--  characters are. The one exception is the bullet of a task item, which is
--  concealed so the checkbox sits where the bullet was.
--
--  The line under the cursor shows the raw markdown in insert and visual mode,
--  to edit it; in normal mode it stays rendered, like concealcursor=nc.
--  Hidden lines (frontmatter, footnotes, todoist queries) come back while the
--  cursor is on them: gg shows the frontmatter, and moving onto a footnote
--  shows it. A wikilink shows raw while the cursor is inside it, as in
--  Obsidian's live preview, so it can be edited and followed (<CR>).
--
--    <leader>om  toggle rendering
-- =============================================================================

local M = {}

local ns = vim.api.nvim_create_namespace('pure_mdview')
local enabled = true

local heading_icons = { '󰲡 ', '󰲣 ', '󰲥 ', '󰲧 ', '󰲩 ', '󰲫 ' }
local bullets = { '●', '○', '◆', '◇' }
local checkbox = { unchecked = '󰄱', checked = '󰄲' }
-- Obsidian's extra states. Markdown does not know them ('- [~] x' is a plain
-- item whose text starts with '[~]'), so render.bullet finds them by text.
-- Box-shaped icons, like the two checkboxes, written as code points: pasted
-- private-use glyphs have been lost in copying before, leaving empty icons.
local extra_states = {
  ['~'] = { '\u{F0856}', 'PureMdTaskProgress' },  -- md-checkbox_intermediate: in progress
  ['!'] = { '\u{F0CE4}', 'PureMdTaskImportant' }, -- md-alert_box_outline: important
  ['>'] = { '\u{F0736}', 'PureMdTaskDeferred' },  -- md-arrow_right_bold_box_outline: deferred
  ['-'] = { '\u{F06F2}', 'PureMdTaskCancelled' }, -- md-minus_box_outline: cancelled
}

-- -----------------------------------------------------------------------------
--  Colours
-- -----------------------------------------------------------------------------
--  Themes rarely know these groups, so each one links to something every
--  theme has. The heading bands are computed: the heading colour mixed into
--  the CursorLine background, so they follow the theme instead of being fixed
--  colours that clash with it.

local function hexToRgb(n) return math.floor(n / 65536) % 256, math.floor(n / 256) % 256, n % 256 end

--- `fg` mixed into `bg` by `amount` (0..1), both as 0xRRGGBB integers.
local function blend(fg, bg, amount)
  local fr, fg_, fb = hexToRgb(fg)
  local br, bg_, bb = hexToRgb(bg)
  local function mix(a, b) return math.floor(a * amount + b * (1 - amount) + 0.5) end
  return mix(fr, br) * 65536 + mix(fg_, bg_) * 256 + mix(fb, bb)
end

local function resolved(name)
  return vim.api.nvim_get_hl(0, { name = name, link = false })
end

local function setHighlights()
  local set = function(name, val) vim.api.nvim_set_hl(0, name, vim.tbl_extend('force', val, { default = true })) end

  -- A transparent theme has no Normal background to shade against, so the
  -- base is CursorLine's (it always has one to be visible), else near black.
  local dark = vim.o.background == 'dark'
  local base = resolved('CursorLine').bg or resolved('Normal').bg or (dark and 0x101010 or 0xf0f0f0)

  for level = 1, 6 do
    set('PureMdH' .. level, { link = '@markup.heading.' .. level .. '.markdown' })
    local fg = resolved('PureMdH' .. level).fg or resolved('Title').fg
    -- Not `default`: recomputed on every call so it follows the heading colour
    -- that render-md.lua assigns per level.
    vim.api.nvim_set_hl(0, 'PureMdH' .. level .. 'Bg', { bg = fg and blend(fg, base, 0.2) or base })
  end

  set('PureMdCode', { bg = base })
  set('PureMdCodeLabel', { link = 'Comment' })
  set('PureMdInlineCode', { bg = base })
  set('PureMdBullet', { link = 'Special' })
  set('PureMdQuote', { link = 'Comment' })
  set('PureMdRule', { link = 'Comment' })
  set('PureMdTable', { link = 'Comment' })
  set('PureMdCheckedText', { link = 'Comment' })
  set('PureMdFootnote', { link = 'Special' })
  set('PureMdLink', { link = '@markup.link.label' })

  -- Checkbox icons: fixed colours, the same in every colorscheme, so a state
  -- always reads the same at a glance. Not `default` and re-applied on
  -- ColorScheme: a theme switch must not restyle them.
  local task_colours = {
    PureMdTaskTodo      = '#8b949e', -- [ ] grey
    PureMdTaskDone      = '#3fb950', -- [x] green
    PureMdTaskProgress  = '#58a6ff', -- [~] blue
    PureMdTaskImportant = '#f85149', -- [!] red
    PureMdTaskDeferred  = '#a371f7', -- [>] purple
    PureMdTaskCancelled = '#6e7681', -- [-] dark grey
  }
  for name, fg in pairs(task_colours) do
    vim.api.nvim_set_hl(0, name, { fg = fg })
  end
end

-- -----------------------------------------------------------------------------
--  Queries
-- -----------------------------------------------------------------------------
local block_query = vim.treesitter.query.parse('markdown', [[
  (atx_heading) @heading
  (fenced_code_block) @code
  [(list_marker_minus) (list_marker_plus) (list_marker_star)] @bullet
  (task_list_marker_unchecked) @unchecked
  (task_list_marker_checked) @checked
  (block_quote) @quote
  (thematic_break) @rule
  (pipe_table) @table
]])

local inline_query = vim.treesitter.query.parse('markdown_inline', [[
  (code_span) @code_span
]])

-- -----------------------------------------------------------------------------
--  Renderers, one per capture
-- -----------------------------------------------------------------------------
--  Each gets the buffer, the node and a `mark(row, col, opts)` helper that
--  skips the raw (cursor) line.

local function lineText(buf, row)
  return vim.api.nvim_buf_get_lines(buf, row, row + 1, false)[1] or ''
end

--- Last row a block node really covers. Blocks end at column 0 of the line
--- after them, which is not part of the block.
local function lastRow(node)
  local _, _, er, ec = node:range()
  return ec == 0 and er - 1 or er
end

local render = {}

function render.heading(buf, node, mark)
  local row = node:start()
  local marker = node:child(0)
  local level = tonumber(marker:type():match('atx_h(%d)_marker'))
  if not level then return end

  -- The #s plus the space after them; the icon is right-aligned in that width
  -- so the heading text does not move.
  local _, sc, _, ec = marker:range()
  local width = ec - sc + 1
  local icon = heading_icons[level]
  local pad = math.max(width - vim.fn.strdisplaywidth(icon), 0)
  mark(row, sc, {
    virt_text = { { string.rep(' ', pad) .. icon, 'PureMdH' .. level } },
    virt_text_pos = 'overlay',
  })
  mark(row, 0, { line_hl_group = 'PureMdH' .. level .. 'Bg' })
end

function render.code(buf, node, mark)
  local first, last = node:start(), lastRow(node)
  for row = first, last do
    mark(row, 0, { line_hl_group = 'PureMdCode' })
  end

  -- Fence lines: cover ```lang with the language as a label.
  local lang = ''
  for child in node:iter_children() do
    if child:type() == 'info_string' then
      lang = vim.treesitter.get_node_text(child, buf):match('^%S+') or ''
    end
  end
  for _, row in ipairs({ first, last }) do
    local text = lineText(buf, row)
    local indent = #text:match('^%s*')
    local label = row == first and lang ~= '' and (' ' .. lang) or ''
    local cover = vim.fn.strdisplaywidth(text) - indent
    mark(row, indent, {
      virt_text = { { label .. string.rep(' ', math.max(cover - vim.fn.strdisplaywidth(label), 0)), 'PureMdCodeLabel' } },
      virt_text_pos = 'overlay',
    })
  end
end

--- Bullets change with depth; a task item's bullet is hidden instead, since
--- the checkbox takes its place.
function render.bullet(buf, node, mark)
  local item = node:parent()
  for child in item:iter_children() do
    if child:type():match('^task_list_marker') then
      local row, sc, _, ec = node:range()
      mark(row, sc, { end_col = ec, conceal = '' })
      return
    end
  end

  -- '- [~] text' and the like: hide the bullet, draw the state's icon over
  -- the '[' and conceal the rest of the box, as for real task items.
  local row, sc, _, ec = node:range()
  local box_col, state = lineText(buf, row):match('()%[([^%]])%]', ec + 1)
  if box_col == ec + 1 and extra_states[state] then
    -- The whole '[~]' is concealed *into* the icon. Treesitter reads '[~]' as
    -- a shortcut link and conceals its brackets itself; an overlay plus a
    -- partial conceal fought with that and swallowed the space after it.
    local icon, hl = unpack(extra_states[state])
    mark(row, sc, { end_col = ec, conceal = '' })
    mark(row, ec, { end_col = ec + 3, conceal = icon, hl_group = hl, priority = 300 })
    return
  end

  local depth = 0
  local parent = item:parent()
  while parent do
    if parent:type() == 'list' then depth = depth + 1 end
    parent = parent:parent()
  end
  local row, col = node:start()
  mark(row, col, {
    virt_text = { { bullets[(depth - 1) % #bullets + 1], 'PureMdBullet' } },
    virt_text_pos = 'overlay',
  })
end

--- The icon covers the '[' and the rest of the box (' ]' / 'x]') is concealed,
--- so the icon sits where the concealed bullet was, level with the bullets of
--- ordinary items. Padding the icon to the box's width instead left a gap.
local function task(buf, node, mark, state)
  local row, sc, _, ec = node:range()
  mark(row, sc, {
    virt_text = { { checkbox[state], state == 'checked' and 'PureMdTaskDone' or 'PureMdTaskTodo' } },
    virt_text_pos = 'overlay',
  })
  mark(row, sc + 1, { end_col = ec, conceal = '' })
  if state == 'checked' then
    -- Dim the item's text, from after the box to the end of the line.
    mark(row, ec, { end_col = #lineText(buf, row), hl_group = 'PureMdCheckedText' })
  end
end

function render.unchecked(buf, node, mark) task(buf, node, mark, 'unchecked') end
function render.checked(buf, node, mark) task(buf, node, mark, 'checked') end

--- Every '>' at the start of the quote's lines, nested ones included. The
--- markers after the first line are not separate nodes, so the lines are
--- scanned instead.
function render.quote(buf, node, mark)
  -- A nested quote is also captured on its own; the outermost one already
  -- scans its lines, so drawing again would stack a second set of bars.
  local parent = node:parent()
  while parent do
    if parent:type() == 'block_quote' then return end
    parent = parent:parent()
  end
  for row = node:start(), lastRow(node) do
    local text = lineText(buf, row)
    local col = 0
    while true do
      local s = text:find('^%s*>', col + 1)
      if not s then break end
      local gt = text:find('>', s, true)
      mark(row, gt - 1, { virt_text = { { '▋', 'PureMdQuote' } }, virt_text_pos = 'overlay' })
      col = gt
    end
  end
end

function render.rule(buf, node, mark)
  local row = node:start()
  local width = vim.api.nvim_win_get_width(0) - vim.fn.getwininfo(vim.api.nvim_get_current_win())[1].textoff
  mark(row, 0, { virt_text = { { string.rep('─', width), 'PureMdRule' } }, virt_text_pos = 'overlay' })
end

--- Pipes become │; the delimiter row (|---|:-:|) becomes ├───┼───┤.
function render.table(buf, node, mark)
  for row = node:start(), lastRow(node) do
    local text = lineText(buf, row)
    local is_delimiter = text:match('^%s*|?[%s:%-|]+$') and text:find('-', 1, true)
    if is_delimiter then
      -- Built from the original (all ASCII) characters: substituting in place
      -- would shift byte offsets, since ─ ├ ┼ ┤ are three bytes each.
      local indent = #text:match('^%s*')
      local first = text:find('|', 1, true)
      local last_pipe = #text - (text:reverse():find('|', 1, true) or 0) + 1
      local out = {}
      for pos = indent + 1, #text do
        local ch = text:sub(pos, pos)
        if ch == '|' then
          table.insert(out, pos == first and '├' or pos == last_pipe and '┤' or '┼')
        elseif ch:match('%s') then
          table.insert(out, ch)
        else
          table.insert(out, '─')
        end
      end
      mark(row, indent, { virt_text = { { table.concat(out), 'PureMdTable' } }, virt_text_pos = 'overlay' })
    else
      local col = 0
      while true do
        local p = text:find('|', col + 1, true)
        if not p then break end
        -- A '\|' is a literal pipe inside a cell, not a border.
        if text:sub(p - 1, p - 1) ~= '\\' then
          mark(row, p - 1, { virt_text = { { '│', 'PureMdTable' } }, virt_text_pos = 'overlay' })
        end
        col = p
      end
      -- Checkboxes in cells. Markdown has no task items inside tables, so
      -- treesitter sees plain text; match the [ ] / [x] literally instead.
      for pos, mark_char in text:gmatch('()%[([ xX])%]') do
        local state = mark_char == ' ' and 'unchecked' or 'checked'
        local icon = checkbox[state]
        mark(row, pos - 1, {
          virt_text = { { icon .. string.rep(' ', 3 - vim.fn.strdisplaywidth(icon)),
            state == 'checked' and 'PureMdTaskDone' or 'PureMdTaskTodo' } },
          virt_text_pos = 'overlay',
        })
      end
    end
  end
end

function render.code_span(buf, node, mark)
  local row, sc, erow, ec = node:range()
  if row ~= erow then return end
  mark(row, sc, { end_col = ec, hl_group = 'PureMdInlineCode' })
end

-- -----------------------------------------------------------------------------
--  Hidden lines: frontmatter and footnotes
-- -----------------------------------------------------------------------------
--  Found by text rather than by treesitter: the markdown parser does not know
--  footnotes, and Obsidian's rule for the frontmatter is simply "the file
--  starts with a --- line".

local superscript = { ['0'] = '⁰', ['1'] = '¹', ['2'] = '²', ['3'] = '³', ['4'] = '⁴',
  ['5'] = '⁵', ['6'] = '⁶', ['7'] = '⁷', ['8'] = '⁸', ['9'] = '⁹' }

--- True when (row, col) is inside a code block or `code`, where [^1] and
--- --- are just text.
local function inCode(buf, row, col)
  local ok, node = pcall(vim.treesitter.get_node, { bufnr = buf, pos = { row, col }, ignore_injections = false })
  while ok and node do
    local t = node:type()
    if t == 'fenced_code_block' or t == 'indented_code_block' or t == 'code_span' then return true end
    node = node:parent()
  end
  return false
end

--- Rows (0-based, inclusive) of the frontmatter, or nil.
local function frontmatter(buf)
  if lineText(buf, 0) ~= '---' then return nil end
  local lines = vim.api.nvim_buf_get_lines(buf, 1, 200, false)
  for i, l in ipairs(lines) do
    if l == '---' or l == '...' then return { 0, i } end
  end
end

--- { first, last } row ranges of footnote definitions between top and bottom:
--- the "[^id]: text" line plus the indented lines that continue it.
local function footnotes(buf, top, bottom)
  local ranges = {}
  local lines = vim.api.nvim_buf_get_lines(buf, top, bottom + 1, false)
  local i = 1
  while i <= #lines do
    local row = top + i - 1
    if lines[i]:match('^ ? ? ?%[%^[^%]]+%]:') and not inCode(buf, row, #lines[i]:match('^%s*')) then
      local last = i
      while lines[last + 1] and lines[last + 1]:match('^\t') or (lines[last + 1] or ''):match('^    %S') do
        last = last + 1
      end
      table.insert(ranges, { row, top + last - 1 })
      i = last + 1
    else
      i = i + 1
    end
  end
  return ranges
end

--- Hide the frontmatter and footnote definitions, except the one the cursor
--- is in, and draw footnote references as superscripts.
--- Returns the hidden-able ranges, so cursor moves can tell when to redraw.
local function hideLines(buf, top, bottom, mark)
  local cursor = vim.fn.line('.') - 1
  local ranges = footnotes(buf, top, bottom)
  local fm = frontmatter(buf)
  if fm then table.insert(ranges, 1, fm) end
  local ok, todoist = pcall(require, 'pure.todoist')
  if ok and todoist.hiddenBlocks then vim.list_extend(ranges, todoist.hiddenBlocks(buf)) end

  for _, r in ipairs(ranges) do
    if cursor < r[1] or cursor > r[2] then
      for row = r[1], r[2] do
        pcall(vim.api.nvim_buf_set_extmark, buf, ns, row, 0, { conceal_lines = '' })
      end
    end
  end

  local lines = vim.api.nvim_buf_get_lines(buf, top, bottom + 1, false)
  for i, text in ipairs(lines) do
    local row = top + i - 1
    for start, id, stop in text:gmatch('()%[%^([^%]]+)%]()') do
      -- Not the label that opens a definition line, and not inside code.
      local is_definition = text:sub(stop, stop) == ':' and not text:sub(1, start - 1):match('%S')
      if not is_definition and not inCode(buf, row, start - 1) then
        local label = id:match('^%d+$') and id:gsub('%d', superscript) or ('^' .. id)
        mark(row, start - 1, {
          end_col = stop - 1,
          conceal = '',
          virt_text = { { label, 'PureMdFootnote' } },
          virt_text_pos = 'inline',
        })
      end
    end
  end
  return ranges
end

local embed_icons = { image = '\u{F02E9}', file = '\u{F0219}' } -- md-image, md-file_document
local image_ext = { png = true, jpg = true, jpeg = true, gif = true, svg = true, webp = true, bmp = true }

--- What Obsidian shows for the inside of a [[wikilink]]: the alias after
--- '|' if there is one, else the target, with '#' sections as ' > '.
local function wikilinkText(inner)
  local alias = inner:match('|(.*)$')
  if alias and alias ~= '' then return alias end
  local target = inner:gsub('|.*$', '')
  local note, rest = target:match('^([^#]*)#(.*)$')
  if not note then return target end
  -- [[#Section]] links inside the same note show just the section.
  local parts = vim.tbl_filter(function(p) return p ~= '' end, vim.split(rest, '#', { plain = true }))
  local shown = table.concat(parts, ' > ')
  return note ~= '' and (note .. ' > ' .. shown) or shown
end

--- The [[wikilink]] (with its '!') under byte column `col` of `text`, as
--- "start:stop" (1-based, stop exclusive), or ''.
local function linkAt(text, col)
  for start, stop in text:gmatch('()%[%[[^%[%]]-%]%]()') do
    if text:sub(start - 1, start - 1) == '!' then start = start - 1 end
    if col + 1 >= start and col + 1 < stop then return start .. ':' .. stop end
  end
  return ''
end

--- The link under the cursor, as a key that changes when the cursor enters
--- or leaves one.
local function cursorLink()
  local row, col = unpack(vim.api.nvim_win_get_cursor(0))
  local key = linkAt(vim.api.nvim_get_current_line(), col)
  return key ~= '' and (row .. ':' .. key) or ''
end

--- [[target|alias]] drawn as its text. Obsidian's own syntax, which the
--- markdown parser does not know (it already hides the URL of [text](url)).
--- The link under the cursor is left raw.
local function wikilinks(buf, top, bottom, mark)
  local lines = vim.api.nvim_buf_get_lines(buf, top, bottom + 1, false)
  local cursor_row, cursor_col = unpack(vim.api.nvim_win_get_cursor(0))
  for i, text in ipairs(lines) do
    local row = top + i - 1
    local raw = row == cursor_row - 1 and linkAt(text, cursor_col) or ''
    for start, inner, stop in text:gmatch('()%[%[([^%[%]]-)%]%]()') do
      local key = (text:sub(start - 1, start - 1) == '!' and start - 1 or start) .. ':' .. stop
      if inner ~= '' and key ~= raw and not inCode(buf, row, start - 1) then
        local shown = wikilinkText(inner)
        -- ![[...]] embeds a note or a file: the '!' becomes an icon.
        if text:sub(start - 1, start - 1) == '!' then
          start = start - 1
          local is_image = inner:gsub('|.*$', ''):lower():match('%.(%a+)$')
          is_image = is_image and image_ext[is_image]
          shown = (is_image and embed_icons.image or embed_icons.file) .. ' ' .. shown
        end
        mark(row, start - 1, {
          end_col = stop - 1,
          conceal = '',
          virt_text = { { shown, 'PureMdLink' } },
          virt_text_pos = 'inline',
        })
      end
    end
  end
end

--- The range of `ranges` holding row `row`, as "first:last", or ''.
local function rangeAt(ranges, row)
  for _, r in ipairs(ranges or {}) do
    if row >= r[1] and row <= r[2] then return r[1] .. ':' .. r[2] end
  end
  return ''
end

-- -----------------------------------------------------------------------------
--  Code fences
-- -----------------------------------------------------------------------------
--  Neovim's own markdown highlights hide the whole ```lang line
--  (conceal_lines), which also hid the language label render.code draws
--  there. Load the same query without that directive; the backticks and
--  the language name are still concealed, the line itself stays.
do
  local parts = {}
  for _, file in ipairs(vim.treesitter.query.get_files('markdown', 'highlights')) do
    local text = table.concat(vim.fn.readfile(file), '\n')
    table.insert(parts, (text:gsub('%(#set! conceal_lines ""%)', '')))
  end
  pcall(vim.treesitter.query.set, 'markdown', 'highlights', table.concat(parts, '\n'))
end

-- -----------------------------------------------------------------------------
--  Driver
-- -----------------------------------------------------------------------------

--- True when `buf` should show rendered markdown.
--- Scratch buffers (buftype set) are skipped unless they opt in with
--- vim.b.pure_mdview = true, as the Todoist task list does.
local function active(buf)
  return enabled and vim.bo[buf].filetype == 'markdown'
    and (vim.bo[buf].buftype == '' or vim.b[buf].pure_mdview == true)
end

--- Redraw the visible part of the current window's buffer.
function M.refresh()
  local buf = vim.api.nvim_get_current_buf()
  vim.api.nvim_buf_clear_namespace(buf, ns, 0, -1)
  if not active(buf) then return end

  local ok, parser = pcall(vim.treesitter.get_parser, buf, 'markdown')
  if not ok or not parser then return end

  -- Only the rows on screen, plus a margin so short scrolls look finished.
  local top = math.max(vim.fn.line('w0') - 1 - 20, 0)
  local bottom = vim.fn.line('w$') + 20
  parser:parse({ top, bottom })

  -- The cursor line is left raw while editing it.
  local mode = vim.fn.mode()
  local raw_row = (mode:match('^[iRvV\22]')) and (vim.fn.line('.') - 1) or -1

  local function mark(row, col, opts)
    if row == raw_row or row < top or row > bottom then return end
    opts.priority = opts.priority or 200
    pcall(vim.api.nvim_buf_set_extmark, buf, ns, row, col, opts)
  end

  parser:for_each_tree(function(tree, ltree)
    local lang = ltree:lang()
    local query = lang == 'markdown' and block_query or lang == 'markdown_inline' and inline_query
    if not query then return end
    for id, node in query:iter_captures(tree:root(), buf, top, bottom + 1) do
      local fn = render[query.captures[id]]
      if fn then fn(buf, node, mark) end
    end
  end)

  local ranges = hideLines(buf, top, bottom, mark)
  wikilinks(buf, top, bottom, mark)
  vim.b[buf].pure_md_hidden = ranges
  vim.b[buf].pure_md_revealed = rangeAt(ranges, vim.fn.line('.') - 1)
  vim.b[buf].pure_md_link = cursorLink()
end

function M.toggle()
  enabled = not enabled
  M.refresh()
  vim.notify('Markdown rendering ' .. (enabled and 'on' or 'off'))
end

local group = vim.api.nvim_create_augroup('PureMdview', { clear = true })

vim.api.nvim_create_autocmd(
  { 'BufWinEnter', 'WinScrolled', 'TextChanged', 'TextChangedI', 'CursorMoved', 'CursorMovedI', 'ModeChanged', 'WinResized' }, {
    group = group,
    callback = function(args)
      if vim.bo[args.buf].filetype ~= 'markdown' then return end
      -- In normal mode the render does not depend on the cursor, so plain
      -- movement needs no redraw -- unless it enters or leaves a hidden block
      -- (frontmatter, footnote). In visual mode the raw line follows it.
      if args.event == 'CursorMoved' and vim.fn.mode() == 'n'
        and rangeAt(vim.b[args.buf].pure_md_hidden, vim.fn.line('.') - 1) == vim.b[args.buf].pure_md_revealed
        and cursorLink() == vim.b[args.buf].pure_md_link then
        return
      end
      -- A note opens on its first line, which would reveal the frontmatter:
      -- start just below it instead, as Obsidian does.
      if args.event == 'BufWinEnter' and vim.fn.line('.') == 1 and active(args.buf) then
        local fm = frontmatter(args.buf)
        if fm then pcall(vim.api.nvim_win_set_cursor, 0, { math.min(fm[2] + 2, vim.fn.line('$')), 0 }) end
      end
      M.refresh()
    end,
  })

-- Scheduled so it runs after render-md.lua's FileType handler, which assigns
-- the per-level heading colours the bands are computed from.
vim.api.nvim_create_autocmd('FileType', {
  group = group,
  pattern = 'markdown',
  callback = function() vim.schedule(function() setHighlights(); M.refresh() end) end,
})
vim.api.nvim_create_autocmd('ColorScheme', { group = group, callback = setHighlights })
setHighlights()

return M

end

-- lua/pure/notify.lua
package.preload["pure.notify"] = function(...)
-- =============================================================================
--  Notifications
-- =============================================================================
--  Replaces mini.notify. Takes over vim.notify and shows each message in a
--  floating window in the top-right corner, newest at the bottom. A message
--  stays for a few seconds (longer for warnings and errors), then goes away;
--  all of them are kept in a history.
--
--    :Notifications        open the history in a split
--    require('pure.notify').get_all()   the history as a Lua list
--
--  Colours: PureNotifyNormal / PureNotifyBorder (link to NormalFloat /
--  FloatBorder); warnings and errors use DiagnosticWarn / DiagnosticError.
-- =============================================================================

local M = {}

local levels = vim.log.levels

--- How long a message stays on screen, per level (ms).
local duration = {
  [levels.ERROR] = 8000,
  [levels.WARN]  = 6000,
}
local default_duration = 4000
local max_width_share = 0.382 -- of the editor width, as mini.notify was set up

local level_hl = {
  [levels.ERROR] = 'DiagnosticError',
  [levels.WARN]  = 'DiagnosticWarn',
}

local level_name = {}
for name, value in pairs(levels) do level_name[value] = name end

vim.api.nvim_set_hl(0, 'PureNotifyNormal', { link = 'NormalFloat', default = true })
vim.api.nvim_set_hl(0, 'PureNotifyBorder', { link = 'FloatBorder', default = true })

local history = {} -- every message, oldest first: { id, msg, level, time }
local active = {}  -- the ones on screen now, in the same order
local next_id = 1

local ns = vim.api.nvim_create_namespace('pure_notify')
local buf, win

-- -----------------------------------------------------------------------------
--  Window
-- -----------------------------------------------------------------------------
local function close()
  if win and vim.api.nvim_win_is_valid(win) then
    vim.api.nvim_win_close(win, true)
  end
  win = nil
end

--- Rebuild the window from `active`: one block of lines per message.
local function render()
  if #active == 0 then return close() end

  if not (buf and vim.api.nvim_buf_is_valid(buf)) then
    buf = vim.api.nvim_create_buf(false, true)
    vim.bo[buf].filetype = 'pure-notify'
  end

  local lines, spans = {}, {}
  for _, item in ipairs(active) do
    local first = #lines
    for _, line in ipairs(vim.split(item.msg, '\n', { plain = true })) do
      table.insert(lines, line)
    end
    table.insert(spans, { first, #lines, level_hl[item.level] })
  end
  vim.api.nvim_buf_set_lines(buf, 0, -1, false, lines)

  vim.api.nvim_buf_clear_namespace(buf, ns, 0, -1)
  for _, span in ipairs(spans) do
    if span[3] then
      vim.api.nvim_buf_set_extmark(buf, ns, span[1], 0, { end_row = span[2], hl_group = span[3], hl_eol = true })
    end
  end

  -- Width is the longest line, capped; the height counts wrapped lines, so a
  -- long error is shown whole instead of cut at the window edge.
  local max_width = math.max(math.floor(vim.o.columns * max_width_share), 20)
  local width = 1
  for _, line in ipairs(lines) do
    width = math.max(width, vim.fn.strdisplaywidth(line))
  end
  width = math.min(width, max_width)
  local height = 0
  for _, line in ipairs(lines) do
    height = height + math.max(1, math.ceil(vim.fn.strdisplaywidth(line) / width))
  end
  height = math.min(height, math.max(vim.o.lines - 4, 1))

  local config = {
    relative = 'editor',
    anchor = 'NE',
    row = vim.o.showtabline == 2 and 1 or 0,
    col = vim.o.columns,
    width = width,
    height = height,
    style = 'minimal',
    border = 'rounded',
    focusable = false,
    zindex = 250,
  }

  if win and vim.api.nvim_win_is_valid(win) then
    vim.api.nvim_win_set_config(win, config)
  else
    config.noautocmd = true
    win = vim.api.nvim_open_win(buf, false, config)
    vim.wo[win].wrap = true
    vim.wo[win].winhighlight = 'NormalFloat:PureNotifyNormal,FloatBorder:PureNotifyBorder'
  end
end

local function remove(id)
  for i, item in ipairs(active) do
    if item.id == id then
      table.remove(active, i)
      break
    end
  end
  render()
end

-- -----------------------------------------------------------------------------
--  API
-- -----------------------------------------------------------------------------

--- Drop-in for vim.notify (same arguments; `opts` is accepted and ignored).
function M.notify(msg, level, opts)
  level = level or levels.INFO
  if level == levels.OFF then return end

  local item = { id = next_id, msg = tostring(msg), level = level, time = os.time() }
  next_id = next_id + 1
  table.insert(history, item)

  -- vim.notify may be called from a libuv callback (a job, an LSP handler)
  -- where windows cannot be touched, so the drawing always waits for the main
  -- loop. The history above is updated right away either way.
  vim.schedule(function()
    table.insert(active, item)
    render()
    vim.defer_fn(function() remove(item.id) end, duration[level] or default_duration)
  end)
end

--- Every message since startup, oldest first. Each entry is a copy.
function M.get_all()
  return vim.deepcopy(history)
end

--- Hide everything on screen now (the history is kept).
function M.clear()
  active = {}
  render()
end

--- Show the history in a scratch split, one line per message line.
function M.showHistory()
  local lines = {}
  for _, item in ipairs(history) do
    local prefix = os.date('%H:%M:%S', item.time) .. ' ' .. (level_name[item.level] or '?') .. ' '
    for i, line in ipairs(vim.split(item.msg, '\n', { plain = true })) do
      table.insert(lines, (i == 1 and prefix or string.rep(' ', #prefix)) .. line)
    end
  end
  if #lines == 0 then lines = { 'No notifications yet.' } end

  vim.cmd('botright new')
  local hbuf = vim.api.nvim_get_current_buf()
  vim.bo[hbuf].buftype = 'nofile'
  vim.bo[hbuf].bufhidden = 'wipe'
  vim.api.nvim_buf_set_lines(hbuf, 0, -1, false, lines)
  vim.bo[hbuf].modifiable = false
  -- pcall: the name is taken while an earlier history split is still open.
  pcall(vim.api.nvim_buf_set_name, hbuf, 'Notifications')
  vim.keymap.set('n', 'q', '<cmd>close<cr>', { buffer = hbuf, desc = 'Close notification history' })
  vim.cmd('normal! G')
end

vim.api.nvim_create_user_command('Notifications', M.showHistory, { desc = 'Show notification history' })

-- Keep the window in the corner when the editor is resized.
vim.api.nvim_create_autocmd('VimResized', {
  group = vim.api.nvim_create_augroup('PureNotify', { clear = true }),
  callback = function() if #active > 0 then render() end end,
})

vim.notify = M.notify

return M

end

-- lua/pure/pairs.lua
package.preload["pure.pairs"] = function(...)
local M = {}

local pair = {
  ['('] = ')',
  ['['] = ']',
  ['{'] = '}',
  ['<'] = '>',
  ['"'] = '"',
  ["'"] = "'",
  ['`'] = '`',
}

local function nextChar()
  local col = vim.api.nvim_win_get_cursor(0)[2]
  return vim.api.nvim_get_current_line():sub(col + 1, col + 1)
end

-- Typing a closer that is already there steps over it instead of inserting a
-- second one. Without this, "[ ]" typed by hand came out as "[ ]]": '[' had
-- already added the ']', and the ']' typed after the space added another.
for open, close in pairs(pair) do
  vim.keymap.set('i', open, function()
    -- Quotes open and close with the same key.
    if open == close and nextChar() == close then return '<Right>' end
    return open .. close .. '<Left>'
  end, { expr = true, noremap = true })

  if open ~= close then
    vim.keymap.set('i', close, function()
      return nextChar() == close and '<Right>' or close
    end, { expr = true, noremap = true })
  end
end

local function delete_pair()
  local cursor = vim.api.nvim_win_get_cursor(0)
  local row = cursor[1] - 1 -- transforma para 0-indexed
  local col = cursor[2]
  local line = vim.api.nvim_get_current_line()
  local char = line:sub(col + 1, col + 1)

  local target_char = pair[char]
  local flags = 'nw'

  if not target_char then
    for o, c in pairs(pair) do
      if char == c then
        target_char = o
        flags = 'bnw'
        break
      end
    end
  end

  if target_char then
    local open_pat = char:match("[%[%(%{]") and "\\" .. char or char
    local close_pat = target_char:match("[%]%}%)]") and "\\" .. target_char or target_char

    if flags == 'bnw' then
      open_pat, close_pat = close_pat, open_pat
    end

    local pair_pos = vim.fn.searchpairpos(open_pat, "", close_pat, flags)

    if pair_pos[1] ~= 0 then
      local p_row, p_col = pair_pos[1] - 1, pair_pos[2] - 1

      if p_row > row or (p_row == row and p_col > col) then
        vim.api.nvim_buf_set_text(0, p_row, p_col, p_row, p_col + 1, {})
        vim.api.nvim_buf_set_text(0, row, col, row, col + 1, {})
      else
        vim.api.nvim_buf_set_text(0, row, col, row, col + 1, {})
        vim.api.nvim_buf_set_text(0, p_row, p_col, p_row, p_col + 1, {})
      end
      vim.notify('pair deleted')
      return
    end
  end

  vim.cmd("normal! x")
end
vim.keymap.set('n', 'dl', delete_pair, { desc = "Delete char and its pair" })

vim.keymap.set('i', '<BS>', function()
  local col = vim.api.nvim_win_get_cursor(0)[2]
  local line = vim.api.nvim_get_current_line()
  local left = line:sub(col, col)
  local right = line:sub(col + 1, col + 1)

  if pair[left] == right then
    return "<BS><Del>"
  end
  return "<BS>"
end, { expr = true })

return M

end

