    vim.api.nvim_set_hl(0, "@markup.heading.4.markdown", { link = "Special" })
    -- Checkbox colours are fixed in pure/mdview.lua (PureMdTask*), not here.

    -- Headings, bullets, checkboxes and the rest are drawn by pure/mdview.lua.
